    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills this bin's post-residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for a perfect chain fit (post_residual == next_item_size).
        if gap == 0.0 {
            score -= 60.0;
        } else {
            // Penalize proportionally to how far the next item is from filling the leftover space.
            score += gap * 0.8;
        }
        // If next item cannot fit here at all, mild penalty (this bin will likely strand space).
        if (next_item_size as u32) > post_residual {
            score += 15.0;
        }
    } else {
        // Last item: pure tightness packing.
        score -= 10.0;
    }

    // Compare against mean residual: placing into a bin whose residual is far below average
    // (i.e., a nearly full bin) is good; placing into a large-residual bin wastes flexibility.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual is tiny, which is fine anyway).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating dead space that is too small for typical items (1..100 range):
    // leftovers below ~10 are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: make it moderately attractive only when current bins would leave
    // large unusable residuals or when many bins are open (spread load late in stream).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 30.0 * progress - 0.2 * open_bins_count as f64;
        // If the next item is huge, keeping current bins' space may be better; discourage new bin.
        if next_item_size >= 60 {
            score += 20.0;
        }
    }

    score
