            score += 10.0; // lookahead cannot use this gap
        }
    } else {
        // Perfect fit: strongly reward closing the bin.
        score -= 25.0;
    }

    // Tight fit reward relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than spreading out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
