    let cap = bin_capacity as f64;
    let n = next_item_size;

    // Harmonic residue classes: reward reusable remainders, punish awkward gaps.
    if pr < 12 {
        score -= 28.0 + (12 - pr) as f64 * 3.0;
        if pr == 0 {
            score -= 14.0;
        }
        if n > 0 && pr >= 1 && pr <= 3 && n > pr {
            score += 5.0;
        }
        if n > 0 && pr >= 1 && pr <= 3 && n == pr {
            score -= 10.0;
        }
        if n > 0 && pr >= n && pr - n <= 1 {
            score -= 9.0;
        }
    } else if pr < 28 {
        let d = (28 - pr) as f64;
        score += 11.0 + d * (1.0 + 0.03 * d);
        if n >= 12 && n <= pr {
            score -= 18.0;
        }
        if n >= 8 && pr >= 2 * n {
            score -= 9.0;
        }
        if n > 0 && pr >= n && (pr - n) < 4 {
            score -= 4.0;
        }
    } else {
        if pr % 5 == 0 { score -= 5.5; }
        if pr % 10 == 0 { score -= 4.5; }
        if pr % 25 == 0 { score -= 3.5; }
        if n > 0 && pr > n && pr - n <= 10 {
            score -= 4.5;
        }
        if n >= 10 {
            let r = pr % n;
            if r > 0 && n - r <= 4 {
                score -= 3.0;
            }
        }
        if n >= 15 && pr >= n + n / 2 {
            score -= 2.5;
        }
        if n > pr && pr > 28 && pr < 45 {
            score += 3.5;
        }
        // NEW: mid-band residue divisibility — a leftover that evenly splits
        // among small future items is premium dead space, not waste.
        if n >= 3 && n <= 12 && pr % n == 0 && pr > 0 {
            score -= 4.0;
        }
    }

    // Dead-space avoidance: residuals too small for the next item are waste.
    let min_useful = if n > 0 { n.min(80) } else { 10 };
    if pr > 0 && pr < min_useful {
        score += (min_useful - pr) as f64 * 6.0;
        if pr <= 5 {
            score += 25.0;
        }
        // NEW: sharper cliff when the waste is provably terminal (no future
        // item can ever be this small in a tight stream).
        if pr < min_useful / 2 {
            score += (min_useful / 2 - pr) as f64 * 4.0;
        }
    }

    // Quadratic waste penalty for large leftovers.
    if pr > 0 {
        let waste_ratio = pr as f64 / cap;
        if waste_ratio > 0.5 {
            score += (waste_ratio - 0.5) * (waste_ratio - 0.5) * 40.0 + (waste_ratio - 0.5) * 10.0;
        }
