    }

    // Tightness scaled by fill ratio.
    let fill_ratio = 1.0 - bin_residual as f64 / cap;
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += tightness * (7.0 + 7.0 * fill_ratio);

    // Deviation from mean residual: nearly-full bins preferred (convex tilt).
    let dev = mean_residual - pr as f64;
    if bin_residual != bin_capacity {
        score += (pr as f64 - mean_residual) * 0.40;
        if dev > 0.0 {
            score -= dev * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity && bin_residual >= item_size {
        score -= 34.0;
        if bin_residual - item_size <= 5 { score -= 10.0; }
        if n > 0 && bin_residual - item_size >= n {
            score -= 6.0;
        }
        let leftover = bin_residual - item_size;
        if n > 0 && leftover > n && leftover - n < 8 && leftover > 30 {
            score += 9.0;
        }
        if leftover == 0 { score -= 6.0; }
    }
    if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 7.5;
    }

    // Open-bin pressure (logarithmic to tolerate many open bins).
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fragmentation = mean_residual / cap;

    if bin_residual != bin_capacity {
        score -= pressure;
        let res_ratio = bin_residual as f64 / cap;
        if res_ratio < 0.25 {
            score -= (0.25 - res_ratio) * 14.0;
        }
        if progress < 0.3 && fragmentation < 0.15 {
            score -= res_ratio * 3.0;
        }
    } else {
        // New-bin candidate: penalize, more so late in the stream.
        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if n as f64 > cap * 0.6 {
            score -= 6.0;
        }
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if n > 0 && bin_capacity - item_size == n {
            score -= 12.0;
        }
        if fragmentation < 0.12 && progress > 0.1 {
            score += 4.0;
        }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if n > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= n {
                let after = fresh_post - n;
                if after == 0 {
                    score -= 18.0;
                } else if after <= n / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
            }
        }
        if pr > 0 && pr <= 8 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core tightness term: quadratic in post_residual (dead space penalized super-linearly)
    let mut score = pr * (1.0 + 0.02 * pr / cap);

    // Smooth non-linear coupling: residual waste matters more as the stream progresses
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Reward filling bins deeply (smooth saturation of fit ratio)
    score -= 25.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    } else {
        // Mild crowding penalty when many bins can fit the item
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily (smooth exponential)
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 20.0 * (-diff / 8.0);
    }

    // New-bin candidate: neutral-ish baseline; discourage early opening, allow it when
    // post_residual of the fresh bin beats typical open-bin residuals late in the stream.
    if bin_residual == bin_capacity {
        score = 45.0 + pr * (0.6 + 0.8 * progress) - 10.0 * progress;
    }

    // Mean residual context: prefer bins whose residual deviates below the mean (use them up)
    if mean_residual > 0.0 {
        score += 0.15 * (pr - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: prefer small post-residual (tight fit)
    let mut score = pr;

    // Normalized residual ratio, smooth polynomial coupling with stream progress
    let r = pr / cap; // in [0,1]
    let p = progress.clamp(0.0, 1.0);

    // Early in the stream: keep residuals flexible (penalize very small residuals less,
    // penalize mid-range residuals more). Late: chase tight fits aggressively.
    let flexibility = (1.0 - p) * (r * (1.0 - r)) * 8.0; // smooth hump favoring mid residuals early
    score += flexibility;

    // Tight-fit reward: smooth cubic decay of reward as residual grows
    let tightness = (1.0 - r).powi(3) * (6.0 + 14.0 * p);
    score -= tightness;

    // Dead-space penalty: residual too small for lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let waste = (nxt - pr) / nxt;
            score += waste * (8.0 + 12.0 * p);
        } else {
            // Reward bins that can also host the next item (chain fit), smoothly
            let chain = 1.0 - (pr - nxt) / cap;
            score -= chain * (2.0 + 4.0 * p);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 5.0 + 10.0 * p;
    }

    // New-bin candidate handling: mildly attractive when many bins are open and residuals
    // are low / stream is early; penalized otherwise so tight fits win.
    if is_new_bin {
        let mean_r_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score = score * 0.0 + 30.0
            - (1.0 - mean_r_norm) * 10.0
            - pressure * 12.0
            - (1.0 - p) * 6.0
            + mean_r_norm * 14.0;
    }

    // Mild global regularization toward low-mean-residual states
    score += (mean_residual / cap).clamp(0.0, 1.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the next item are wasted.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Unusable gap for lookahead: penalize proportionally to how close
            // it is to being useful (worst just below next_item_size).
            let gap = (next_item_size - post_residual) as f64;
            score += 12.0 * (1.0 - gap / next_item_size as f64);
        } else {
            // Usable gap: mild reward scaled by slack for the next item.
            score -= 2.0 * ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Absolute dead-zone penalty: any residual in (0, 10] is essentially trash
    // since items are >= 1; small residuals rarely reusable.
    if post_residual > 0 && post_residual <= 10 {
        score += 8.0;
    }

    // Tight-fit reward: filling a bin nearly exactly.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 3 {
        score -= 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when it enables a good future fit or
    // open-bin pressure is high; otherwise penalize.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
        // Prefer new bin when current item leaves a good residual for lookahead,
        // or when existing bins are heavily fragmented.
        let lookahead_fit = if next_item_size > 0 && post_residual >= next_item_size { 6.0 } else { 0.0 };
        score += 25.0 - lookahead_fit - 3.0 * pressure - 5.0 * progress;
    }

    // Open-bin pressure: mildly prefer using already-open bins over spreading.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins whose residual deviates favorably from the mean (tighter bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
