    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // coarse capacity-fraction buckets. Leftovers in "usable" classes
    // (multiples of common item sizes) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / cap;

    // Harmonic bucket index: floor(10 * fraction) gives 10 classes.
    let bucket = (frac * 10.0).floor() as i64;

    // Buckets 0-2 (tiny leftovers < 30) are dead space -> penalize hard.
    // Buckets 6-9 (large leftovers) are reusable -> reward.
    match bucket {
        0 => score += 25.0,
        1 => score += 15.0,
        2 => score += 8.0,
        3 => score += 2.0,
        5 => score -= 3.0,
        6 => score -= 5.0,
        7 => score -= 7.0,
        8 => score -= 9.0,
        9 => score -= 10.0,
        _ => {}
    }

    // Modular arithmetic: post_residual divisible by small item sizes (10, 20, 25, 50)
    // leaves space that future items of those classes can perfectly fill.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 4.0; }
        if post_residual % 20 == 0 { score -= 2.0; }
        if post_residual % 25 == 0 { score -= 2.0; }
        if post_residual % 50 == 0 { score -= 3.0; }
    } else {
        // Perfect fit: strongly reward closing the bin completely.
        score -= 30.0;
    }

    // Integer-division threshold on next_item_size: does the lookahead item
    // fit exactly into the post-residual? Reward exact and near fits.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // Slack after the next item would also land here.
            let next_slack = post_residual - next_item_size;
            score -= 6.0 * (1.0 - next_slack as f64 / cap);
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled
            // by how far off it is (harmonic mismatch).
            let mismatch = (next_item_size - post_residual) as f64;
            score += 0.1 * mismatch.min(30.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Tight-fill coupling: reward placements that leave residual below
    // the smallest plausible item class only when the bin is nearly full.
    if post_residual < 10 && post_residual > 0 {
        score -= 8.0;
    }

    // Progression-aware: early in the stream keep bins flexible
    // (penalize very low residuals), later commit to tight packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 && post_residual > 0 && post_residual < 20 {
        score += 6.0 * (0.3 - progress) / 0.3;
    }

    // Mean-residual context: if this bin's residual is far below the mean,
    // it is already the "dreg" bin; filling it is good.
    let bin_res = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (bin_res - mean_residual) / mean_residual;
        if dev < 0.0 {
            score -= 2.0 * (-dev).min(1.0);
        }
    }

    // New-bin candidate: neutral base cost so it only wins when open bins
    // all score poorly (their bonuses can push below this).
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the next item are wasted.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Unusable gap for lookahead: penalize proportionally to how close
            // it is to being useful (worst just below next_item_size).
            let gap = (next_item_size - post_residual) as f64;
            score += 12.0 * (1.0 - gap / next_item_size as f64);
        } else {
            // Usable gap: mild reward scaled by slack for the next item.
            score -= 2.0 * ((post_residual - next_item_size) as f64 / bin_capacity as f64);
