    }

    // Prefer bins whose residual is tight relative to mean residual (compact bins).
    let residual_gap = post_residual as f64 - mean_residual;
    if residual_gap < 0.0 {
        score -= residual_gap.abs() * 0.5;
    } else {
        score += residual_gap * 0.3;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize choosing the new empty bin when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 50.0 + (open_bins_count as f64) * 2.0;
        // But if no other bin fits well, allow opening a new bin.
        if fitting_bins_count == 0 || (post_residual as f64) < item_size as f64 * 0.2 {
            score -= 150.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins for flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize less when item nearly fills the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
