        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual < next_item_size {
            score -= 5.0; // new bin preserves space for a bigger next item
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins.
    if open_bins_count > 3 && mean_residual > 20.0 && bin_residual < bin_capacity {
        score -= 2.0 * (mean_residual / 100.0).min(1.0);
    }

    // Lookahead chain: if next item fits here too, reward stacking.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

