    let progress = step_index as f64 / total_items.max(1) as f64;
    if fill_ratio < 0.5 && progress < 0.5 {
        score += 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pn = pr / bin_capacity as f64;
    let t = progress;

    // Smooth polynomial in progress: early stream penalizes waste mildly,
    // late stream penalizes waste more strongly (quadratic/cubic ramp).
    let ramp = 0.5 + 1.5 * t * t + 0.5 * t * t * t;
    score += pn * pn * 40.0 * ramp;

    // Perfect-fit reward, amplified late in the stream (smooth coupling).
    let perfect = ((post_residual == 0) as i32 as f64);
    score -= perfect * (20.0 + 60.0 * t * t);

    // Tight-fit reward: post_residual small relative to capacity, smooth in t.
    let tight = (1.0 - pn).max(0.0);
    score -= tight * tight * 8.0 * (0.3 + 0.7 * t);

    // Dead-space penalty: residual unusable if next item won't fit.
    let next_item_size = next_item_size as f64;
    if next_item_size > 0.0 && pr > 0.0 && next_item_size > pr {
        let blocked = (next_item_size - pr) / bin_capacity as f64;
        score += blocked * blocked * 50.0 * (0.4 + 0.6 * t);
    } else if next_item_size > 0.0 && next_item_size <= pr {
        // Reward bins that can also serve the lookahead item.
        score -= 6.0 * (pr - next_item_size).max(0.0) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * t;
    }

    // New-bin candidate: penalize opening new bins early, allow late when
    // existing residuals are fragmented (mean_residual low).
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64);
        score += 30.0 * (1.0 - t) + 10.0 * (1.0 - fragmentation).max(0.0);
        // Late stream: new bins acceptable if waste would be large elsewhere.
        score -= 15.0 * t * t * fragmentation;
    }

    // Mild preference for fuller bins overall (best-fit bias), scaled by t.
    score -= (item_size as f64 / bin_capacity as f64) * 5.0 * (0.5 + t);

    // Penalize scattering across many open bins late in stream.
    score += (open_bins_count as f64 / (total_items.max(1) as f64)) * 30.0 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement (capacity / 4 granularity).
    // Classes: [0..=2] perfect, (2..10] small dead, (10..25] medium, (25..50] large, >50 huge.
    let class = match post_residual {
        0 => 0u32,
        1..=2 => 1,
        3..=10 => 2,
        11..=25 => 3,
        26..=50 => 4,
        _ => 5,
    };

    // Reward tight fits strongly.
    score -= match class {
        0 => 60.0,
        1 => 40.0,
        2 => 8.0,
        3 => 0.0,
        4 => -4.0, // leaving big residual is mildly bad
        _ => -10.0,
    };

    // Modulo-harmonic bonus: residuals divisible by small harmonics (5, 10, 20, 25)
    // are more likely reusable by typical item sizes.
    if post_residual > 0 {
        if post_residual % 5 == 0 { score -= 3.0; }
        if post_residual % 10 == 0 { score -= 3.0; }
        if post_residual % 20 == 0 || post_residual % 25 == 0 { score -= 3.0; }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, huge reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item fits: residual class compatibility
            let slack = post_residual - next_item_size;
            if slack <= 5 { score -= 25.0; } else { score -= (slack as f64).ln() * 4.0; }
        } else {
            // next item cannot use this residual; penalize small residuals more
            if post_residual < 10 { score += 12.0; }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 0.5 * (post_residual as f64);
    }

    // New-bin candidate handling: empty bin gets baseline competition.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive early in the stream or when many bins
        // already exist but fits are poor; baseline keeps it competitive but
        // tight fits in existing bins still win.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: fresh bin useful
        }
        if fitting_bins_count > 0 && mean_residual > (2.0 * item_size as f64) {
            score += 10.0; // existing bins have room; discourage new bin
        }
    }

    // Slight preference to fill bins with lower mean residual (consolidation).
    score += 0.05 * mean_residual;

    // Mild penalty when many bins compete equally (prefer any, tiny tiebreak).
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps (< 10, min item size) are heavily penalized.
    if post_residual < 10 {
        score += 40.0; // dead space is pure waste
    } else if post_residual < 20 {
        score += 12.0; // nearly-unusable gap: only tiny items can use it
    } else if post_residual < 35 {
        score += 4.0; // moderately awkward gap
    } else {
        // Reward placements leaving large, reusable residual space.
        score -= 0.10 * (post_residual as f64);
    }

    // Perfect fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit reward: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.8 {
        score -= 8.0 * (fill_ratio - 0.8);
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 3.0; // next item still fits, keep bin alive
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0; // next item cannot use this gap
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating into existing bins
    // (penalize the new-bin candidate, which has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 10.0 + 2.5 * open_bins_count as f64;
        // If few bins are open and residual is huge, opening a new bin is fine.
        if open_bins_count <= 2 {
            score -= 12.0;
        }
    }

    // Slight preference for bins with residual above the mean residual (keeps tighter bins for tight fits).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Early in the stream, be more permissive about opening bins; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate baseline: keep it neutral-ish, slightly penalized so we
    // only open a new bin when existing fits look genuinely bad.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 + (open_bins_count as f64) * 1.5;
        // If no other bin fits well, opening fresh is attractive.
        if fitting_bins_count == 0 {
            score -= bin_capacity as f64 * 0.4;
        }
        return score;
    }

    // --- 2-step lookahead: does the next item fit exactly / well here? ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: consume the bin completely over two steps.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits; reward tighter leftover after the chain.
            let chain_left = (post_residual - next_item_size) as f64;
            score -= 25.0 - chain_left * 0.25;
        } else {
            // Next item won't fit here: dead space risk proportional to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    }

    // Reward leaving residuals that are small but still "usable" relative to mean.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < mean_residual.max(1.0) {
        score -= 6.0; // tighter than average: good compaction
    } else if pr > mean_residual {
        score += (pr - mean_residual) * 0.12; // looser than average: mild penalty
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Very tight fits (small post_residual) are excellent placements.
    if pr <= 10.0 {
        score -= 15.0;
    }

    // Late in the stream, prefer closing out bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (best-fit style), slightly superlinear in wasted space.
    let waste = post_residual as f64;
    score += 0.15 * waste * waste / bin_capacity as f64;

    // Reward near-perfect packing: exact fill is heavily favored.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item can follow here: mild bonus proportional to how snugly.
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use this residual: penalize large dead residuals.
            score += 0.05 * (next_item_size as f64).min(post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual < 5 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large and the item is big.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Penalize new bins mildly by default; relax when mean residual is high
        // (existing bins are fragmented) and item is large.
        let mut new_bin_score = 25.0 + 20.0 * item_frac;
        new_bin_score -= 30.0 * (mean_residual / bin_capacity as f64) * item_frac;
        // Late in the stream, be more conservative about opening bins.
        new_bin_score += 10.0 * progress;
        // If nothing fits anywhere, new bin is the only option (fitting_bins_count==0
        // never happens here since empty bin fits, but guard anyway).
        score = new_bin_score;
        // Exact large items deserve a fresh bin.
        if item_size == bin_capacity {
            score = -100.0;
        }
    }

    // Global fragmentation pressure: when many bins are open with high mean residual,
    // encourage consolidating items into existing bins.
    if bin_residual != bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        score -= 8.0 * frag * (open_bins_count as f64).ln().max(1.0);
    }

    // Time horizon: early on, allow slightly more exploration of new bins;
    // later, tighten packing by penalizing residuals more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth polynomial coupling of post-residual with stream progress
    let poly = x * (1.0 + 0.8 * t) - 1.5 * x * x * (1.0 - t) + 0.7 * x * x * x * t;

    let mut score = pr + 20.0 * poly;

    // Reward tight fits smoothly (small post residual), stronger late in stream
    score -= 30.0 * (1.0 - x).powi(3) * (0.5 + t);

    // Penalize leaving residuals that cannot fit the lookahead item smoothly
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let gap = ((next_item_size as f64 - pr) / cap).max(0.0);
        score += (1.0 - fits_next) * (8.0 + 25.0 * gap * (0.5 + t));
        // Reward post-residual that exactly accommodates the next item
        score -= fits_next * 12.0 * (1.0 - ((pr - next_item_size as f64) / cap).abs());
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.6 + 0.4 * t);
    }

    // New-bin candidate: keep it mildly unattractive unless residuals are poor
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * t - 0.15 * open_bins_count as f64 * (1.0 - t);
        // strongly prefer new bin if existing residuals are fragmented
        score -= (mean_residual / cap - 0.2).max(0.0) * 20.0;
    }

    // Mild preference to spread across many bins early, consolidate late
    score += (open_bins_count as f64) * (1.0 - t) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: quantize into capacity fractions
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // 0..1

    // Penalize residuals that fall into "dead zones" where few item sizes can fit.
    // Class boundaries via integer division on post_residual.
    let cls = post_residual / 10; // 0..10 classes
    let dead_penalty = match cls {
        0 => -8.0,            // perfect / near-perfect fit: reward heavily
        1 => -4.0,            // residual 10-19: many items fit, good
        2 => -2.0,
        3 => 0.0,
        4 => 2.0,
        5 => 4.0,             // residual ~50: moderately awkward
        6 => 3.0,
        7 => 5.0,
        8 => 6.0,
        9 => 4.0,
        _ => -6.0,            // residual ~100: empty bin class
    };
    score += dead_penalty;

    // Modulo-arithmetic coupling: reward residuals that are congruent to common
    // item sizes (10, 20, 25, 50) so future items tile the leftover space exactly.
    if post_residual % 10 == 0 { score -= 3.0; }
    if post_residual % 25 == 0 { score -= 2.0; }
    if post_residual % 50 == 0 { score -= 2.0; }
    if post_residual % 20 == 0 { score -= 1.5; }

    // Exact fill is best possible.
    if post_residual == 0 { score -= 20.0; }

    // Lookahead: if next item exactly matches the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 15.0; }
        else if next_item_size <= post_residual {
            // next residual after hypothetical lookahead placement
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 || next_post == 0 { score -= 4.0; }
            score -= (next_post as f64).min(10.0) * 0.2;
        } else {
            // next item can't use the leftover: penalize big wasted residuals
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins),
    // keeping loose bins available for larger future items.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Stream progression: early on, be pickier about waste; late, just fill anything.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only open a new bin when the current bin would leave a large awkward residual
    // and many bins are already open (avoid bin proliferation).
    if bin_residual == bin_capacity {
        score = 45.0
            + (post_residual as f64) * 0.3
            - (open_bins_count as f64) * 1.5
            - progress * 5.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0; // fresh bin can absorb the lookahead too
        }
        if item_size >= 60 {
            score -= 10.0; // big items are fine in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized
    // because they can never host items of size >= 10... but sizes can be as small as 1,
    // so treat gaps < 4 as truly dead (min item size 1), and 4..=12 as low-utility gaps.
    if post_residual > 0 && post_residual < 4 {
        score += 60.0; // completely dead space
    } else if post_residual >= 4 && post_residual <= 12 {
        score += 25.0; // low-utility gap
    }

    // Reward very tight fits (near-perfect packing)
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize if next item would leave another dead gap here
    if next_item_size > 0 && next_item_size < post_residual && post_residual - next_item_size < 4 {
        score += 18.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // Open-bin pressure: opening a new bin is expensive when many bins are open.
    if bin_residual == bin_capacity {
        score += 18.0 + 2.5 * open_bins_count as f64;
        // But a new bin is acceptable if no open bin fits well (post_residual here is capacity - item)
        if post_residual <= 10 {
            score -= 30.0;
        }
    } else {
        // Mild reward for keeping bins consolidated
        score -= 0.3 * open_bins_count as f64;
    }

    // Prefer bins with residuals below the mean (fill the emptier bins first)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Slight preference for using fuller bins relative to capacity
    score += 0.1 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Early stream: be a bit more willing to open bins (long horizon to consolidate later)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, but scale so exact matches dominate.
    score = post_residual as f64 * 1.0;

    // --- 2-step lookahead: does the NEXT item fit in the leftover? ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        if post_residual == next_item_size {
            // Perfect chaining: this bin will be exactly filled by the next item.
            score -= 60.0 + nxt;
        } else if post_residual >= next_item_size {
            // Next item still fits: leftover is "usable".
            let slack = post - nxt;
            score -= 25.0 + 0.5 * slack.min(20.0);
        } else {
            // Dead space: next item cannot use the leftover.
            let waste = nxt - post;
            // Penalize proportionally to how close we came to fitting (near-miss = worst).
            score += 15.0 + 1.2 * (waste as f64).min(nxt);
            // Extra penalty if the dead space is small and thus truly unusable.
            if post < 10.0 {
                score += 10.0;
            }
        }
    }

    // --- Relative-to-mean coupling: prefer filling bins that are already tight ---
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = res_f / mean_residual;
        // Bins with less residual than average are tighter -> favor placing here
        // (keeps loose bins available for large future items).
        score += 0.35 * (rel - 1.0) * mean_residual.min(50.0);
    }

    // --- Last-chance bin: if this is the ONLY bin that fits, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is costly; only attractive if no open bin offers a
        // good (near-perfect) fit. Judge by how much dead space existing bins
        // would leave vs. this fresh bin's full residual.
        let fresh_value = post_residual as f64;
        // Penalize new bins mildly so only truly bad fits in open bins trigger opening.
        score += 30.0;
        // But reward the fresh bin if the item is large (hard to place later)
        // and open bins are scarce or very loose.
        if item_size >= 60 {
            score -= 10.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // If many loose bins exist, discourage spreading.
        if mean_residual > item_size as f64 * 2.0 && open_bins_count > 2 {
            score += 25.0;
        }
        let _ = fresh_value;
    }

    // --- Slight stream-position modulation: late in the stream, consolidation matters more ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (post_residual == 0) as i32 as f64 * 2.0;

    // Reward exact fills (post_residual == 0) strongly at any time.
    if post_residual == 0 {
        score -= 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small leftover space.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * (1.0 - tight) * (1.0 - tight);

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose residual can still host the next item,
    // penalize residuals that are too small to be useful (dead space).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < 10 {
            score += 6.0; // tiny unusable sliver
        }
        // Bonus for leaving exactly a usable chunk for the next item.
        if post_residual >= next_item_size && post_residual < next_item_size + 15 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize spreading across too many open bins; encourage consolidation
    // when many bins are open relative to stream length.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = (open_bins_count as f64) / (1.0 + mean_residual / 20.0);
    score += 0.05 * crowding * (0.5 + progress);

    // Global pressure: if mean residual is low, conserve capacity by
    // preferring bins that keep post_residual near multiples of small items.
    if mean_residual < 25.0 && post_residual > 0 {
        score += 3.0;
    }

    // New-bin candidate: make it moderately attractive only when the item
    // fits poorly everywhere (large item, high mean residual, many bins).
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) / (bin_capacity as f64);
        let mut nb = 20.0 - 18.0 * (1.0 - poor_fit); // tight fits elsewhere -> new bin unattractive
        if next_item_size > 0 && post_residual >= next_item_size {
            nb += 6.0; // fresh bin can host the next item too
        }
        if fitting_bins_count == 0 {
            nb -= 30.0; // no alternative
        }
        if open_bins_count == 0 {
            nb -= 50.0;
        }
        score += nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;
    let fit_ratio = if fitting_bins_count > 0 { 1.0 / fitting_bins_count as f64 } else { 1.0 };

    // Base: quadratic in post_residual (penalize large AND tiny dead space asymmetrically)
    let mut score = pr * (1.0 + 0.5 * pr / cap);

    // Smooth stream-progress coupling: later in stream, favor tighter fills more strongly
    let progress_weight = 0.4 + 0.6 * t * t;
    score -= progress_weight * norm_item * (cap - pr);

    // Interaction: post_residual vs next item size — reward bins whose residual
    // smoothly matches the lookahead item (smooth gaussian-like coupling)
    let diff = pr - norm_next * cap;
    score -= 6.0 * (-(diff * diff) / (2.0 * 25.0)).exp();

    // Penalize when many bins fit (less urgency to use this one), smooth in fit count
    score += 3.0 * (1.0 - fit_ratio) * (1.0 - t);

    // Mean-residual deviation coupling: prefer bins near the mean residual early,
    // diverge from mean later (keeps flexibility early, consolidates late)
    let dev = (pr - mean_residual) / cap;
    score += (0.5 - t) * dev * dev * 40.0;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * t;
    }

    // New-bin candidate handling: empty bin gets moderate score; only attractive
    // when residuals of open bins are large relative to item
    if bin_residual == bin_capacity {
        score = 0.55 * cap + 0.3 * mean_residual - 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 create "dead zones"
    // (residuals that no typical item can use). Penalize small positive residues.
    let r = post_residual;
    let residue_class = r % 10;
    if r > 0 {
        match residue_class {
            0 => score -= 12.0,             // perfect decade fit, highly reusable
            1 | 9 => score += 9.0,          // nearly unusable sliver
            2 | 8 => score += 5.0,
            3 | 7 => score -= 1.0,
            4 | 6 => score -= 2.0,
            _ => score -= 3.0,              // class 5: half-capacity friendly
        }
    }

    // Integer-division thresholds on post_residual: classify usability bands
    let band = r / 20; // 0..5
    score += match band {
        0 => 15.0,                          // dead space (<20)
        1 => 4.0,
        2 => 0.0,
        3 => -3.0,
        _ => -6.0,                          // roomy bin
    } as f64;

    // Capacity fraction coupling: how full will the bin be
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill_frac;               // reward tighter packing

    // Lookahead harmonic coupling: does next_item_size fit the post_residual
    // exactly (same harmonic class)?
    if next_item_size > 0 {
        if next_item_size <= r {
            let combined = r - next_item_size;
            score -= 6.0;
            if combined % 10 == 0 {
                score -= 8.0;               // chain of perfect fits
            }
            if combined < 10 && combined > 0 {
                score += 10.0;              // creates sliver after lookahead
            }
        } else {
            score += 4.0;                   // next item won't chain here
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: neutral-ish, but attractive only if
    // open bins are crowded or the item is large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let crowding = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        score = 30.0 + 20.0 * item_frac - 5.0 * progress + 2.0 * crowding.min(10.0);
        if item_size > 60 {
            score -= 12.0;                  // big items deserve fresh bins
        }
        if fitting_bins_count <= 1 {
            score -= 25.0;                  // no real alternative anyway
        }
    }

    // Slight tie-break by bin tightness relative to mean residual
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let min_useful = 10.0f64.min(bin_capacity as f64 * 0.1);
    if post_residual > 0 && (post_residual as f64) < min_useful {
        // Dead space: gap too small for any plausible item.
        score += (min_useful - post_residual as f64) * 4.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Tight fit reward: leaving only a small but still usable gap.
    if post_residual > 0 && (post_residual as f64) >= min_useful && (post_residual as f64) <= 20.0 {
        score -= 8.0;
    }

    // Lookahead: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 20.0 {
                score -= 10.0 - slack * 0.4;
            }
        }
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // over opening new bins (penalize the empty new-bin candidate).
    let pressure = open_bins_count as f64 * 0.8 + progress * 5.0;
    if bin_residual == bin_capacity {
        score += 12.0 + pressure;
    } else {
        score -= pressure * 0.3;
    }

    // Prefer bins below mean residual (larger leftover than average) slightly less;
    // bins tighter than average absorb space better.
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills this bin's post-residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for a perfect chain fit (post_residual == next_item_size).
        if gap == 0.0 {
            score -= 60.0;
        } else {
            // Penalize proportionally to how far the next item is from filling the leftover space.
            score += gap * 0.8;
        }
        // If next item cannot fit here at all, mild penalty (this bin will likely strand space).
        if (next_item_size as u32) > post_residual {
            score += 15.0;
        }
    } else {
        // Last item: pure tightness packing.
        score -= 10.0;
    }

    // Compare against mean residual: placing into a bin whose residual is far below average
    // (i.e., a nearly full bin) is good; placing into a large-residual bin wastes flexibility.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual is tiny, which is fine anyway).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating dead space that is too small for typical items (1..100 range):
    // leftovers below ~10 are nearly unusable.
