        let d = (28 - post_residual) as f64;
        score += 11.0 + d * (1.0 + 0.03 * d);
        // NEW: escape hatch — if the leftover gap exactly equals a plausible
        // follow-up item, this "awkward" gap is actually a perfect chain slot.
        if next_item_size >= 12 && next_item_size <= post_residual {
            score -= 18.0;
        }
    } else {
        let pr = post_residual;
        if pr % 5 == 0 { score -= 5.5; }
        if pr % 10 == 0 { score -= 4.5; }
        if pr % 20 == 0 { score -= 3.5; }
        if pr % 25 == 0 { score -= 3.5; }
        if pr % 50 == 0 { score -= 4.0; }
        // Mid-range sweet spots (30-45) absorb common small follow-ups.
        if pr >= 30 && pr <= 45 { score -= 3.0; }
        // Residuals just above the next item are prime chain targets.
        if next_item_size > 0 && pr > next_item_size && pr - next_item_size <= 10 {
            score -= 4.5;
        }
        // Residual that is a near-multiple of the next item size can host
        // repeated follow-ups of similar size — mildly valuable.
        if next_item_size >= 8 && pr >= 2 * next_item_size && pr % next_item_size <= 6 {
            score -= 2.0;
        }
        // NEW: dead-zone detector for the large-residual regime — residuals in
        // (50, capacity-30) that match no divisibility pattern and cannot host
        // the next item are the main source of wasted space; penalize softly.
