    // Dead-space ratio: fraction of the bin that becomes unusable after placement.
    // Penalize placements whose leftover is too small for any realistic future item.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 8.0 {
        score += 10.0 - dead * 0.9; // tiny leftover = dead space
    }

    // Harmonic residue classes: reward highly reusable remainders, punish dead space.
    if post_residual < 12 {
        // Near-zero residual is trash; the closer to zero, the worse (sharpened slope).
        score -= 28.0 + (12 - post_residual) as f64 * 3.0;
        if post_residual == 0 {
            score -= 14.0;
        }
        if post_residual >= 1 && post_residual <= 3 && next_item_size > post_residual {
            score += 5.0;
        }
        if post_residual >= 1 && post_residual <= 3 && next_item_size == post_residual {
            score -= 10.0;
        }
    } else if post_residual < 28 {
        // Awkward mid-range gap: penalize (smaller gap = worse), softened tail.
        let d = (28 - post_residual) as f64;
        score += 11.0 + d * (1.0 + 0.03 * d);
        if next_item_size >= 12 && next_item_size <= post_residual {
            score -= 18.0;
        }
        if next_item_size >= 8 && post_residual >= 2 * next_item_size {
            score -= 9.0;
        }
        if next_item_size >= 6 && next_item_size <= post_residual && post_residual % next_item_size == 0 {
            score -= 9.0;
        }
        // NEW: leftover after eating the next item stays reusable.
        if next_item_size > 0 && post_residual > next_item_size {
            let npr = post_residual - next_item_size;
            if npr >= 12 && npr < 28 {
                score -= 4.0;
            }
        }
    } else {
        let pr = post_residual;
        if pr % 5 == 0 { score -= 5.5; }
        if pr % 10 == 0 { score -= 4.5; }
        if pr % 20 == 0 { score -= 3.5; }
        if pr % 25 == 0 { score -= 3.5; }
        if pr % 50 == 0 { score -= 4.0; }
        if pr >= 30 && pr <= 45 { score -= 3.0; }
        if next_item_size > 0 && pr > next_item_size && pr - next_item_size <= 10 {
            score -= 4.5;
        }
        if next_item_size >= 8 && pr >= 2 * next_item_size && pr % next_item_size <= 6 {
            score -= 2.0;
        }
        if next_item_size > 0 && pr > 50 && next_item_size > pr
            && pr % 5 != 0 && pr % 10 != 0 {
            score += 3.0;
        }
        if next_item_size >= 10 {
            let r = pr % next_item_size;
            if r > 0 && next_item_size - r <= 4 {
                score -= 3.0;
            }
        }
        // Large residual that still holds the next item plus a half-slot
        // is prime real estate — keep it alive.
        if next_item_size >= 15 && pr >= next_item_size + (next_item_size / 2) {
            score -= 2.5;
        }
        // NEW: residual that fits next item twice exactly is a double pocket.
        if next_item_size >= 10 && pr == 2 * next_item_size {
            score -= 8.0;
        }
    }

    // Two-step lookahead: chain fits strongly rewarded.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 52.0;
        } else if next_item_size < post_residual {
            let npr = post_residual - next_item_size;
            if npr < 12 { score -= 15.0; }
            if npr % 10 == 0 { score -= 5.0; }
            if npr % 25 == 0 { score -= 3.5; }
            if npr >= next_item_size && npr < 40 { score -= 2.5; }
            if npr >= 20 { score -= 4.0; }
            if npr >= next_item_size + 20 { score -= 2.0; }
            if npr < 12 && npr >= 6 && next_item_size < 20 {
                score += 4.0;
            }
            if next_item_size >= 6 && npr >= 2 * next_item_size {
                score -= 3.5 + (npr / next_item_size.max(1)) as f64;
            }
            if npr > 15 && npr < 25 && npr % 5 != 0 {
                score += 2.5;
            }
            // Chain landing exactly on zero is the ideal compaction outcome.
            if npr == 0 {
                score -= 20.0;
            }
            // NEW: chain leaves a pocket that still holds next item again.
            if npr >= next_item_size && npr % next_item_size == 0 {
                score -= 4.0;
            }
        } else {
            let shortfall = next_item_size - post_residual;
            score += 12.0 + shortfall as f64 * 0.06;
            if shortfall <= 4 { score -= 6.0; }
        }
    } else {
        score -= 8.0;
    }

    // Tightness: prefer bins whose residual is close to the item size,
    // scaled by fill ratio so nearly-full bins dominate tightness ties.
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * (7.0 + 7.0 * fill_ratio);

    // Deviation from mean residual: nearly-full bins preferred, sharpened.
    score += (post_residual as f64 - mean_residual) * 0.40;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity && bin_residual >= item_size {
        score -= 34.0;
        if bin_residual - item_size <= 5 { score -= 10.0; }
        if next_item_size > 0 && bin_residual - item_size >= next_item_size {
            score -= 6.0;
        }
        let leftover = bin_residual - item_size;
        if next_item_size > 0 && leftover > next_item_size && leftover - next_item_size < 8 && leftover > 30 {
            score += 9.0;
        }
    }
    if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 7.5;
    }

    // New-bin candidate: attractive only when open bins are fragmented or item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 37.0 + fragmentation * 24.0 - progress * 7.0;
        if item_size > 55 {
            score -= 13.0 + (item_size - 55) as f64 * 0.30;
        }
        if next_item_size >= 55 {
            score += 16.0;
        }
        if open_bins_count < 3 {
            score -= 10.0;
        }
        if fragmentation > 0.45 && item_size < 40 {
            score += 7.0;
        }
        if next_item_size > 0 && item_size < bin_residual && bin_residual - item_size == next_item_size {
            score += 22.0;
        }
        if item_size < 25 && mean_residual > item_size as f64 * 2.0 {
            score += 6.0;
        }
        if progress > 0.65 {
            score += 8.0 + (progress - 0.65) as f64 * 34.0;
        }
        if progress >= 0.25 && progress <= 0.65 && item_size <= 45 {
            score += (45 - item_size) as f64 * 0.22 * (1.0 - fragmentation).max(0.0);
        }
        if fitting_bins_count >= 4 && item_size < 35 {
            score -= 5.0;
        }
        if next_item_size > 20 && mean_residual < next_item_size as f64 * 0.8 {
            score -= 6.0;
        }
        // Fresh bin hosting the next item cleanly (residual == next item
        // after placement) is a strong compaction play — open eagerly.
        if next_item_size > 0 && item_size <= bin_capacity - next_item_size
            && bin_capacity - item_size == next_item_size {
            score -= 12.0;
        }
        // NEW: fresh bin that can host next item after this one with exact
        // zero leftover after two placements — perfect pair opening.
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size
            && (bin_capacity - item_size - next_item_size) < 4 {
            score -= 8.0;
        }
    }

    // Mild open-bin pressure to discourage needless spreading.
    score += 0.1 * open_bins_count as f64;

    score
}

