    let mid = 0.5 - (norm_pr - 0.5) * (norm_pr - 0.5); // peaks at norm_pr=0.5
    score += 8.0 * mid * cap * (1.0 - progress);

    // Lookahead: reward bins whose post-residual can hold the next item (smooth interaction).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let fit_quality = 1.0 - (pr - n) / cap;
            score -= 15.0 * fit_quality * (0.5 + progress);
        } else {
            let gap = (n - pr) / cap;
            score += 10.0 * gap * gap * cap;
        }
    }

