    // into common small item sizes (1..=50). Leftovers landing on multiples
    // of 10 / 25 / 50 are more reusable, so reward them.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -40.0 // perfect fill, best possible outcome
    } else {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus -= 6.0; }
        if pr % 25 == 0 { bonus -= 3.0; }
        if pr % 5 == 0 { bonus -= 1.5; }
        // integer-division thresholds: tiny unusable slivers are bad
        let sliver = pr < 10;
        if sliver { bonus += 8.0; }
        bonus
    };
    score += harmonic_bonus;

    // Coupling with lookahead: if the next item exactly fills the post
    // residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // next item fits: leftover class after the pair matters
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 { score -= 4.0; }
            if pr2 < 10 { score += 4.0; }
        } else {
            // next item cannot use this bin's leftover: mild penalty
            score += 2.0;
        }
    }

