        }
        // New-bin refinement: a fresh bin leaving tight, reusable post
        // residual is high quality — soften the opening penalty.
        if post_residual > 0 && post_residual <= 10 {
            score -= 5.0;
        }
        // NEW: if the current item nearly fills the fresh bin outright,
        // opening is clearly justified — reward decisively.
