        score -= pressure;
        if progress < 0.3 && fragmentation < 0.15 {
            score -= (bin_residual as f64 / cap) * 3.0;
        }
        // Deep-fill bias: bins closest to closure get a stronger tilt.
        let res_ratio = bin_residual as f64 / cap;
        if res_ratio < 0.25 {
            score -= (0.25 - res_ratio) * 14.0;
        }
        // NEW: scarcity coupling — when few bins can fit the item, favor the
        // bin that leaves the smallest post-residual (best-fit under scarcity).
        if fitting_bins_count <= 3 {
