        }
    } else {
        if pr % 5 == 0 { score -= 5.5; }
        if pr % 10 == 0 { score -= 4.5; }
        if pr % 25 == 0 { score -= 3.5; }
        if n > 0 && pr > n && pr - n <= 10 {
            score -= 4.5;
