pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;

    // Dead-space avoidance scaled to what's actually usable next.
    let min_useful = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        score += (min_useful - post_residual) as f64 * 6.0;
        if post_residual <= 5 {
            score += 25.0;
        }
        if post_residual < min_useful / 2 {
            score += (min_useful / 2 - post_residual) as f64 * 4.0;
        }
    }

    // Tight fit reward: quadratic near-full bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.80 {
        score -= (fit_ratio - 0.80) * (fit_ratio - 0.80) * 90.0;
    }
    if fit_ratio > 0.97 {
        score -= 14.0;
        if post_residual == 0 {
            score -= 6.0;
        }
    }
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: prefer using the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
        let leftover = bin_residual - item_size;
        if leftover <= 5 { score -= 8.0; }
        if next_item_size > 0 && leftover > next_item_size && leftover - next_item_size < 8 {
            score += 7.0;
        }
    }
    if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fragmentation = mean_residual / cap;

    // Residual "primed" relative to next item.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let gap = bin_residual as i64 - next_item_size as i64;
        if gap >= 0 && gap < 12 {
            score -= 8.0 - gap as f64 * 0.5;
        } else if gap < 0 && (-gap) < next_item_size as i64 {
            score += (-gap) as f64 * 0.30;
        }
    }

    if bin_residual != bin_capacity {
        score -= pressure;
        if progress < 0.3 && fragmentation < 0.15 {
            score -= (bin_residual as f64 / cap) * 3.0;
        }
        // Deep-fill bias — bins whose residual is already small are closest
        // to closure; tilt harder as residual shrinks (refined curve).
        let res_ratio = bin_residual as f64 / cap;
        if res_ratio < 0.25 {
            score -= (0.25 - res_ratio) * 18.0;
        } else if res_ratio < 0.40 {
            score -= (0.40 - res_ratio) * 4.0;
        }
    } else {
        // New-bin candidate: penalize, more so late in the stream.
        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if next_item_size as f64 > cap * 0.6 {
            score -= 6.0;
        }
        if mean_residual > cap * 0.35 {
            score -= 4.0;
        }
        if post_residual > 0 && post_residual <= 8 {
            score -= 5.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 12.0;
        }
        if fragmentation < 0.12 && progress > 0.1 {
            score += 4.0;
        }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if next_item_size > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= next_item_size {
                let after = fresh_post - next_item_size;
                if after == 0 {
                    score -= 18.0;
                } else if after <= next_item_size / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
            }
        }
        // Fragmented open bins make a fresh bin attractive.
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
    }

    // Prefer bins whose residual is below average, with convex tilt.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= dev * 0.20;
        if dev > 0.0 {
            score -= dev * 0.08;
        }
    }

    // Lookahead: reward when next item fits snugly in post residual.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 10.0;
    }
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 14.0 + (item_size as f64 / cap) * 4.0;
    }

    // Three-item chain potential.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next > 0 && after_next <= 12 {
            score -= 5.0;
        }
        if after_next >= next_item_size + next_item_size / 2 && after_next <= 2 * next_item_size {
            score -= 3.0;
        }
        if next_item_size >= 3 && next_item_size <= 12 && after_next % next_item_size == 0 {
            score -= 3.5;
        }
        // NEW: extended chain — residual left after two more hypothetical
        // medium items; strong divisibility suggests multi-item chains.
        let two_more = after_next as i64 - next_item_size as i64;
        if two_more >= 0 && two_more <= 4 {
            score -= 4.0;
        }
    }

    // Quadratic waste penalty for large leftovers.
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap;
        if waste_ratio > 0.5 {
            score += (waste_ratio - 0.5) * (waste_ratio - 0.5) * 40.0 + (waste_ratio - 0.5) * 10.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
        // Escalating terminal-waste penalty — dead space below smallest items.
        if post_residual <= 3 && next_item_size > post_residual {
            score += 12.0;
        }
        // Mid-band dead zone — residuals that neither fit the next item nor
        // are near-zero are the main source of wasted bins.
        if next_item_size > 4 && post_residual < next_item_size && post_residual > 3 {
            score += (next_item_size - post_residual) as f64 * 0.65;
        }
        // NEW: awkward mid-range residual band (10..25) rarely reusable by
        // typical item sizes; penalize unless it exactly matches the next item.
        if post_residual >= 10 && post_residual <= 25 && next_item_size > 0
            && post_residual != next_item_size && post_residual < next_item_size + 6 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement gets a strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual (mod 10 buckets): dead space in the
    // smallest "waste class" is more reusable by typical small items.
    let class = post_residual % 10;
    score -= (10 - class) as f64 * 0.8;

    // Fractional residual tiers: residual in [50,100) keeps half-bin usability.
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 15.0;
    } else if post_residual >= bin_capacity / 4 {
        score -= 5.0;
    } else {
        score += 10.0; // small slivers are nearly dead space
    }

    // Integer-division threshold: can the lookahead item exactly fill the remainder?
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // chain completion: this bin + next item = full bin
        } else if next_item_size <= post_residual {
            score -= 25.0;
            // harmonic pairing: post_residual % next_item_size small => good future fit
            score -= (post_residual % next_item_size.max(1)) as f64 * 0.5;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when existing bins would leave big waste.
    if bin_residual == bin_capacity {
        let waste_if_open = (bin_residual - item_size) as f64;
        let best_existing = if fitting_bins_count > 0 {
            mean_residual.min(bin_residual as f64)
        } else {
            bin_residual as f64
        };
        // Penalize opening a new bin unless it yields a notably better fit
        // than the average open bin, and prefer it late in the stream when
        // many bins are open.
        score = waste_if_open + 20.0
            - (mean_residual - waste_if_open).max(0.0) * 1.5
            + (open_bins_count as f64).ln().max(0.0) * 5.0;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 5.0; // new bin keeps room for similar next item
        }
    }

    // Mild stream-progression pressure: late in stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0;

    // Slight preference for fuller bins overall.
    score -= (bin_residual - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;

    // Dead-space avoidance scaled to what's actually usable next.
    let min_useful = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        score += (min_useful - post_residual) as f64 * 6.0;
        if post_residual <= 5 {
            score += 25.0;
        }
        if post_residual < min_useful / 2 {
            score += (min_useful / 2 - post_residual) as f64 * 4.0;
        }
    }

    // Tight fit reward: quadratic near-full bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.80 {
        score -= (fit_ratio - 0.80) * (fit_ratio - 0.80) * 90.0;
    }
    if fit_ratio > 0.97 {
        score -= 14.0;
        if post_residual == 0 {
            score -= 6.0;
        }
    }
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: prefer using the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
        let leftover = bin_residual - item_size;
        if leftover <= 5 { score -= 8.0; }
        if next_item_size > 0 && leftover > next_item_size && leftover - next_item_size < 8 {
            score += 7.0;
        }
    }
    if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fragmentation = mean_residual / cap;

    // Residual "primed" relative to next item.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let gap = bin_residual as i64 - next_item_size as i64;
        if gap >= 0 && gap < 12 {
            score -= 8.0 - gap as f64 * 0.5;
        } else if gap < 0 && (-gap) < next_item_size as i64 {
            score += (-gap) as f64 * 0.30;
        }
    }

    if bin_residual != bin_capacity {
        score -= pressure;
        if progress < 0.3 && fragmentation < 0.15 {
            score -= (bin_residual as f64 / cap) * 3.0;
        }
        // Deep-fill bias, sharpened: escalate convexly as residual shrinks,
        // with the ramp tuned to the typical small-item tail (<= 25% of cap).
        let res_ratio = bin_residual as f64 / cap;
        if res_ratio < 0.25 {
            let d = 0.25 - res_ratio;
            score -= d * d * 60.0 + d * 8.0;
        }
        // NEW: closure momentum — bins whose residual is within one small
        // item of closing are worth finishing now rather than spreading load.
        if next_item_size > 0 && bin_residual >= next_item_size
            && bin_residual - next_item_size <= bin_capacity / 20 {
            score -= 9.0;
        }
    } else {
        // New-bin candidate: penalize, more so late in the stream.
        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if next_item_size as f64 > cap * 0.6 {
            score -= 6.0;
        }
        if mean_residual > cap * 0.35 {
            score -= 4.0;
        }
        if post_residual > 0 && post_residual <= 8 {
            score -= 5.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 12.0;
        }
        if fragmentation < 0.12 && progress > 0.1 {
            score += 4.0;
        }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if next_item_size > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= next_item_size {
                let after = fresh_post - next_item_size;
                if after == 0 {
                    score -= 18.0;
                } else if after <= next_item_size / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
            }
        }
        // Fragmented open bins make a fresh bin attractive.
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
        // NEW: large-item isolation — big items opening a fresh bin leave
        // predictable room; reward when the leftover still fits the next item.
        if item_size > 60 && next_item_size > 0 && bin_capacity - item_size >= next_item_size {
            score -= 5.0;
        }
    }

    // Prefer bins whose residual is below average, with convex tilt.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= dev * 0.20;
        if dev > 0.0 {
            score -= dev * 0.05;
        }
    }

    // Lookahead: reward when next item fits snugly in post residual.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 10.0;
    }
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 14.0 + (item_size as f64 / cap) * 4.0;
    }

    // Three-item chain potential.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next > 0 && after_next <= 12 {
            score -= 5.0;
        }
        if after_next >= next_item_size + next_item_size / 2 && after_next <= 2 * next_item_size {
            score -= 3.0;
        }
        if next_item_size >= 3 && next_item_size <= 12 && after_next % next_item_size == 0 {
            score -= 3.5;
        }
    }

    // Quadratic waste penalty for large leftovers.
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap;
        if waste_ratio > 0.5 {
            score += (waste_ratio - 0.5) * (waste_ratio - 0.5) * 40.0 + (waste_ratio - 0.5) * 10.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
        // Escalating terminal-waste penalty — dead space below smallest items.
        if post_residual <= 3 && next_item_size > post_residual {
            score += 12.0;
        }
        // Mid-band dead zone penalty, slightly softened to avoid over-shunning
        // residuals that could still absorb a following small item.
        if next_item_size > 4 && post_residual < next_item_size && post_residual > 3 {
            score += (next_item_size - post_residual) as f64 * 0.50;
        }
        // NEW: exact-fill chain bonus — residuals that are a clean multiple of
        // the next item size signal easy future closure.
        if next_item_size >= 2 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap < 10 can never hold the smallest item (sizes >= 1 here,
    // but tiny gaps are statistically dead space for typical streams).
    let dead_threshold: f64 = 12.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        // Quadratic blow-up near zero gap: the smaller the dead space, the worse.
        score += (dead_threshold - pr) * (dead_threshold - pr) * 0.8;
    }

    // Reward near-perfect fits (waste <= small epsilon) strongly.
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 3.0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement chains beautifully; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }
    // If next item does NOT fit in post residual but would fit this bin's
    // current residual, penalize (we are wasting a good slot).
    if next_item_size > 0 && post_residual < next_item_size && bin_residual >= next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins; opening a new
    // bin (bin_residual == bin_capacity) gets a mild fixed cost that grows
    // with how many bins are already open relative to stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 6.0 * progress + 0.15 * open_bins_count as f64;
    } else {
        // Slight bonus for using an existing bin, scaled by scarcity of fits.
        if fitting_bins_count == 1 {
            score -= 20.0; // last-chance bin: use it rather than open a new one
        }
        score -= 2.0;
    }

    // Prefer bins whose residual is close to the mean (balanced usage),
    // penalize outliers that would strand capacity.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild overall pressure on number of open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
