        }
        if n > 0 && pr >= n && pr - n <= 1 {
            score -= 9.0;
        }
    } else if pr < 28 {
        let d = (28 - pr) as f64;
        score += 11.0 + d * (1.0 + 0.03 * d);
        if n >= 12 && n <= pr {
            score -= 18.0;
        }
        if n >= 8 && pr >= 2 * n {
            score -= 9.0;
        }
        if n > 0 && pr >= n && (pr - n) < 4 {
            score -= 4.0;
        }
    } else {
        if pr % 5 == 0 { score -= 5.5; }
        if pr % 10 == 0 { score -= 4.5; }
        if pr % 25 == 0 { score -= 3.5; }
        if n > 0 && pr > n && pr - n <= 10 {
            score -= 4.5;
        }
        if n >= 10 {
            let r = pr % n;
            if r > 0 && n - r <= 4 {
                score -= 3.0;
            }
        }
        if n >= 15 && pr >= n + n / 2 {
