        score += (n - pr) as f64 * 0.20;
    }

    // NEW: three-item chain potential bonus.
    if n > 0 && pr > n {
        let after_next = pr - n;
        if after_next > 0 && after_next <= 12 {
            score -= 2.5;
        }
        if n >= 3 && n <= 12 && after_next % n == 0 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match bonus decaying with distance to next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (30.0 / (1.0 + gap)).min(30.0);
        // Penalize leftover slightly larger than next item (dead space unusable now).
        if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 8.0;
        }
    }

    // Compare post_residual against mean residual of open bins:
    // leaving a residual near the mean keeps flexibility.
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev;

    // Penalize tiny unusable residuals (dead space), unless it's a perfect match.
    if next_item_size == 0 || post_residual != next_item_size {
        if post_residual < 10 && post_residual > 0 {
            score += 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Late in the stream, prefer tighter packing (lower post residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * pr * progress;

    // New-bin candidate: keep it attractive only when open bins are quite full
    // and no good lookahead match exists.
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - (mean_residual / bin_capacity as f64);
        let good_lookahead = next_item_size > 0 && post_residual == next_item_size;
        if good_lookahead {
            score += 100.0; // never open a new bin when a perfect match exists
        } else if avg_fullness < 0.55 {
            score += 35.0; // open bins still roomy: discourage new bin
        } else {
            score -= 5.0 * avg_fullness; // bins mostly full: new bin viable
        }
    }

    score
}

