    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits: exact or near-exact placements get strong discounts.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always take it
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead: if the next item can exactly fill this bin's post-residual,
    // strongly favor placing here to enable a perfect follow-up.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 120.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits too: mild bonus proportional to how snugly both pack.
        score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit in the leftover: penalize dead space a bit.
        score += 6.0;
