        } else if gap < 0 && (-gap) < n as i64 && bin_residual != bin_capacity {
            score += (-gap) as f64 * 0.30;
        }
    } else {
        score -= 8.0;
    }

    // Tightness scaled by fill ratio.
    let fill_ratio = 1.0 - bin_residual as f64 / cap;
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += tightness * (7.0 + 7.0 * fill_ratio);

    // Deviation from mean residual: nearly-full bins preferred.
    score += (pr as f64 - mean_residual) * 0.40;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity && bin_residual >= item_size {
        score -= 34.0;
        if bin_residual - item_size <= 5 { score -= 10.0; }
        if n > 0 && bin_residual - item_size >= n {
            score -= 6.0;
        }
        let leftover = bin_residual - item_size;
        if n > 0 && leftover > n && leftover - n < 8 && leftover > 30 {
            score += 9.0;
        }
        if leftover == 0 { score -= 6.0; }
    }
    if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 7.5;
    }

    // Open-bin pressure (logarithmic to tolerate many open bins).
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fragmentation = mean_residual / cap;

    if bin_residual != bin_capacity {
        score -= pressure;
        let res_ratio = bin_residual as f64 / cap;
        if res_ratio < 0.25 {
            score -= (0.25 - res_ratio) * 14.0;
        }
        if progress < 0.3 && fragmentation < 0.15 {
            score -= res_ratio * 3.0;
        }
        // NEW: strongest tilt toward bins that are already nearly closed,
        // but only when the post residual still serves the next item.
        if res_ratio < 0.12 && (n == 0 || pr >= n) {
            score -= 6.0;
        }
    } else {
        // New-bin candidate: penalize, more so late in the stream.
        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if n as f64 > cap * 0.6 {
            score -= 6.0;
        }
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if n > 0 && bin_capacity - item_size == n {
            score -= 12.0;
        }
        if fragmentation < 0.12 && progress > 0.1 {
            score += 4.0;
        }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if n > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= n {
                let after = fresh_post - n;
                if after == 0 {
                    score -= 18.0;
                } else if after <= n / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
                // NEW: fresh-bin chain — residual after two items still reusable.
                if after >= n {
                    score -= 2.5;
                }
            } else {
                // Fresh bin wasted on an item that leaves a dead gap.
                score += (n - fresh_post) as f64 * 0.4;
            }
        }
        if pr > 0 && pr <= 8 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / cap;
    let res_ratio = post_residual as f64 / cap;

    // Reward tight fits: non-linear penalty on wasted space (quadratic coupling)
    let waste = res_ratio * res_ratio;
    score += waste * cap * (0.6 + 0.8 * progress);

    // Reward perfect fill strongly
    if post_residual == 0 {
        score -= cap * (1.5 + progress);
    }

    // Last-chance bonus: only one bin can fit this item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 20.0 * progress;
    }

    // Scarcity coupling: fewer fitting bins -> favor using this bin
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= scarcity * (8.0 + 10.0 * fit_ratio);

    // Lookahead: if next item fits the post residual, reward leaving usable space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let snug = 1.0 - ((post_residual as f64 - nxt) / cap).abs();
            score -= 6.0 + 10.0 * snug * (1.0 - progress);
        } else {
            // post-residual too small for next item: penalize dead space
            let dead = post_residual as f64 / cap;
            score += dead * dead * 10.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidating
    let pressure = mean_residual / cap;
    score += pressure * (3.0 * open_bins_count as f64).min(12.0) * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity {
        let base_penalty = 18.0 + 30.0 * (1.0 - progress);
        let relief = if fitting_bins_count == 0 { 0.0 } else { fitting_bins_count as f64 };
        score += base_penalty - relief.min(15.0);
        // late in stream, opening fresh bins is more acceptable
        score -= 25.0 * progress * progress;
    }

    // Smooth non-linear stream coupling on residual itself
    score *= 1.0 + 0.15 * (progress * std::f64::consts::PI).sin();

    score
}

