        score += (min_useful - pr) as f64 * 6.0;
        if pr <= 5 {
            score += 25.0;
        }
        if pr < min_useful / 2 {
            score += (min_useful / 2 - pr) as f64 * 4.0;
        }
        // Mid-band dead zone: penalize the just-below-next-item band harder.
        if n > 4 && pr > 3 && pr < n {
            score += (n - pr) as f64 * 0.55;
