    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;

    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: which "slot" does leftover space fall in? ---
    // Class 0: perfect fit (post_residual == 0) -> strong reward
    // Class 1: post_residual is itself a plausible item size (1..=80) -> reward if next item matches
    // Class 2: dead space (post_residual smaller than any possible next use) -> penalize
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else {
        // Lookahead harmony: does the leftover exactly host the next item?
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 55.0; // exact harmonic chain
            } else if next_item_size <= post_residual {
                // leftover fraction usable by next item
                let fill = next_item_size as f64 / post_residual as f64;
                score -= 25.0 * fill;
            } else {
                // next item cannot use this leftover at all
                score += 8.0;
            }
        }

        // Dead-space penalty: leftover below typical small-item scale is wasted.
        // Use integer-division thresholds on post_residual as harmonic bands.
        let band = post_residual / 10; // harmonic band 0..=10
        match band {
            0 => score += 30.0,          // 1..9 : nearly unusable dead space
            1 => score += 12.0,          // 10..19: only tiny items fit
            2 => score += 4.0,           // 20..29
            3 => score -= 2.0,           // 30..39
            4 => score -= 6.0,           // 40..49
            5 => score -= 8.0,           // 50..59
            _ => {}                      // large leftover: neutral (new-bin-like)
        }

        // Modulo coupling: leftover divisible into common item chunks is valuable.
        if post_residual % 10 == 0 {
            score -= 6.0; // aligns with 10-unit granularity
        }
        if post_residual % 20 == 0 {
            score -= 4.0; // extra harmony on 20-unit multiples
        }
        if post_residual % 25 == 0 {
            score -= 3.0;
        }
    }

    // --- Last-chance bonus: if this is the only fitting bin, avoid forcing a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate calibration ---
    // New bin: residual == capacity, post_residual = capacity - item_size.
    // It should win only when no open bin offers a decent (harmonic) fit.
    if bin_residual == bin_capacity {
        // Neutral baseline: score is just post_residual (large leftover).
        // Slight penalty scaling with stream progress so late in the stream
        // we prefer consolidating into open bins.
        score -= 5.0 * (1.0 - progress);
        // Penalize opening new bins when many bins are already open with slack.
        score += 0.5 * open_bins_count as f64;
    }

    // --- Contextual coupling with mean residual ---
    // If this bin's leftover is far below the mean residual, we are compacting well.
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        score -= 0.15 * mean_gap.min(50.0);
    } else {
        score += 0.10 * (-mean_gap).min(50.0);
    }

    // Small tie-breaker favoring tighter fits as stream progresses.
    score += 0.05 * progress * post_residual as f64;

    score
}

