    // Open-bin pressure (logarithmic to tolerate many open bins).
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fragmentation = mean_residual / cap;

    if bin_residual != bin_capacity {
        score -= pressure;
        let res_ratio = bin_residual as f64 / cap;
        if res_ratio < 0.25 {
            score -= (0.25 - res_ratio) * 14.0;
        }
        if progress < 0.3 && fragmentation < 0.15 {
            score -= res_ratio * 3.0;
        }
        // NEW: convex pull toward closure — bins with the smallest residuals
        // relative to the mean get an escalating tilt to finish them off.
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= (dev * 0.10).min(6.0);
        }
    } else {
        // New-bin candidate: penalize, more so late in the stream.
        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if n as f64 > cap * 0.6 {
            score -= 6.0;
        }
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if n > 0 && bin_capacity - item_size == n {
            score -= 12.0;
        }
        if fragmentation < 0.12 && progress > 0.1 {
            score += 4.0;
        }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if n > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= n {
                let after = fresh_post - n;
                if after == 0 {
                    score -= 18.0;
                } else if after <= n / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
            }
        }
        if pr > 0 && pr <= 8 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity.max(1) as f64;
    let n = next_item_size;

    // Harmonic residue classes: reward reusable remainders, punish awkward gaps.
    if pr < 12 {
        score -= 28.0 + (12 - pr) as f64 * 3.0;
        if pr == 0 {
            score -= 14.0;
        }
        if n > 0 && pr >= 1 && pr <= 3 && n > pr {
            score += 5.0;
        }
        if n > 0 && pr >= 1 && pr <= 3 && n == pr {
            score -= 10.0;
        }
        if n > 0 && pr >= n && pr - n <= 1 {
            score -= 9.0;
        }
    } else if pr < 28 {
        let d = (28 - pr) as f64;
        score += 11.0 + d * (1.0 + 0.03 * d);
        if n >= 12 && n <= pr {
            score -= 18.0;
        }
        if n >= 8 && pr >= 2 * n {
            score -= 9.0;
        }
        if n > 0 && pr >= n && (pr - n) < 4 {
            score -= 4.0;
        }
    } else {
        if pr % 5 == 0 { score -= 5.5; }
        if pr % 10 == 0 { score -= 4.5; }
        if pr % 25 == 0 { score -= 3.5; }
        if n > 0 && pr > n && pr - n <= 10 {
            score -= 4.5;
        }
        if n >= 10 {
            let r = pr % n;
            if r > 0 && n - r <= 4 {
                score -= 3.0;
            }
        }
        if n >= 15 && pr >= n + n / 2 {
            score -= 2.5;
        }
        if n > pr && pr > 28 && pr < 45 {
            score += 3.5;
        }
    }

    // Dead-space avoidance: residuals too small for the next item are waste.
    let min_useful = if n > 0 { n.min(80) } else { 10 };
    if pr > 0 && pr < min_useful {
        score += (min_useful - pr) as f64 * 6.0;
        if pr <= 5 {
            score += 25.0;
        }
        // Borrowed from best: extra dead-zone tilt for residuals well below next item.
        if pr < min_useful / 2 {
            score += (min_useful / 2 - pr) as f64 * 4.0;
        }
        if pr <= 3 && n > pr {
            score += 12.0;
        }
    }

    // Quadratic waste penalty for large leftovers.
    if pr > 0 {
        let waste_ratio = pr as f64 / cap;
        if waste_ratio > 0.5 {
            score += (waste_ratio - 0.5) * (waste_ratio - 0.5) * 40.0 + (waste_ratio - 0.5) * 10.0;
        }
        if n > 0 && pr < n {
            score += (n - pr) as f64 * 0.45;
        }
    }

    // Tight fit reward: quadratic near-full bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.80 {
        score -= (fit_ratio - 0.80) * (fit_ratio - 0.80) * 90.0;
    }
    if fit_ratio > 0.97 {
        score -= 14.0;
        if pr == 0 {
            score -= 6.0;
        }
    }
    if pr == 0 {
        score -= 30.0;
    }

    // Two-step lookahead: chain fits strongly rewarded.
    if n > 0 {
        if n == pr {
            score -= 52.0;
        } else if n < pr {
            let npr = pr - n;
            if npr < 12 { score -= 15.0; }
            if npr % 10 == 0 { score -= 5.0; }
            if npr % 25 == 0 { score -= 3.5; }
            if npr >= n && npr < 40 { score -= 2.5; }
            if npr >= 20 { score -= 4.0; }
            if n >= 6 && npr >= 2 * n {
                score -= 3.5 + (npr / n.max(1)) as f64;
            }
            if npr > 15 && npr < 25 && npr % 5 != 0 {
                score += 2.5;
            }
            if npr > 0 && npr <= 12 {
                score -= 5.0;
            }
            if n >= 3 && n <= 12 && npr % n == 0 {
                score -= 3.5;
            }
        } else {
            let shortfall = n - pr;
            score += 12.0 + shortfall as f64 * 0.06;
            if shortfall <= 4 { score -= 6.0; }
        }
    } else {
        score -= 8.0;
    }

    // Tightness scaled by fill ratio.
    let fill_ratio = 1.0 - bin_residual as f64 / cap;
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += tightness * (7.0 + 7.0 * fill_ratio);

    // Deviation from mean residual: nearly-full bins preferred, convex tilt.
    let dev = mean_residual - pr as f64;
    score -= dev * 0.40;
    if dev > 0.0 {
        score -= dev * 0.10;
    }

    // Deep-fill bias: bins with small residuals are closest to closure.
    let res_ratio = bin_residual as f64 / cap;
    if bin_residual != bin_capacity && res_ratio < 0.25 {
        score -= (0.25 - res_ratio) * 14.0;
    }

    // Open-bin pressure: logarithmic to discourage needless spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fragmentation = mean_residual / cap;

    if bin_residual != bin_capacity {
        score -= pressure;
        if progress < 0.3 && fragmentation < 0.15 {
            score -= res_ratio * 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity && bin_residual >= item_size {
        score -= 34.0;
        let leftover = bin_residual - item_size;
        if leftover <= 5 { score -= 10.0; }
        if n > 0 && leftover >= n {
            score -= 6.0;
        }
        if n > 0 && leftover > n && leftover - n < 8 && leftover > 30 {
            score += 9.0;
        }
        if leftover == 0 { score -= 6.0; }
    }
    if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 7.5;
    }

    // New-bin candidate: attractive only when open bins are fragmented or item is large.
    if bin_residual == bin_capacity {
        score += 37.0 + fragmentation * 24.0 - progress * 7.0 + pressure;
        if item_size > 55 {
            score -= 13.0 + (item_size - 55) as f64 * 0.30;
        }
        if n >= 55 {
            score += 16.0;
        }
        if open_bins_count < 3 {
            score -= 10.0;
        }
        if fragmentation > 0.45 && item_size < 40 {
            score += 7.0;
        }
        if n > 0 && bin_residual - item_size == n {
            score += 22.0;
        }
        if item_size < 25 && mean_residual > item_size as f64 * 2.0 {
            score += 6.0;
        }
        if progress > 0.65 {
            score += 8.0 + (progress - 0.65) * 34.0;
        }
        if progress >= 0.25 && progress <= 0.65 && item_size <= 45 {
            score += (45 - item_size) as f64 * 0.22 * (1.0 - fragmentation).max(0.0);
        }
        if fitting_bins_count >= 4 && item_size < 35 {
            score -= 5.0;
        }
        if n > 20 && mean_residual < n as f64 * 0.8 {
            score -= 6.0;
        }
        if n > 0 && item_size <= bin_capacity - n && bin_capacity - item_size == n {
            score -= 12.0;
        }
        if n > 0 && pr % 10 == 0 && pr <= n {
            score += 9.0;
        }
        if pr > 0 && pr <= 8 {
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        // Pair-completion lookahead in a fresh bin (borrowed from best).
        if n > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= n {
                let after = fresh_post - n;
                if after == 0 {
                    score -= 18.0;
                } else if after <= n / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
            }
        }
        // Fragmented open bins make a fresh bin attractive.
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1..=3)
    // are almost certainly wasted; penalize them heavily.
    if post_residual > 0 && post_residual < 4 {
        score += 60.0 - (post_residual as f64) * 10.0; // gap 1 -> +50, gap 3 -> +30
    }
    // Slightly larger but still awkward gaps (4..=8) get a moderate penalty.
    if post_residual >= 4 && post_residual < 9 {
        score += 12.0 - (post_residual as f64) * 0.8;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 3 {
        score -= 10.0; // partial offset for near-perfect fills
    }

    // Reward filling a bin that would otherwise be the item's only option
    // (last-chance bin before opening a new one).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead synergy: if the next item fits exactly in the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // Open-bin pressure: discourage scattering across many bins, but only
    // mildly, so tight fits still dominate.
    score += open_bins_count as f64 * 0.6;

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no open bin offers a good (small) post_residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; scales with stream progress so
        // early on we are slightly more willing to open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 12.0 * (1.0 - progress);
        // If current item nearly fills a fresh bin, opening is great.
        if item_size >= 90 {
            score -= 20.0;
        }
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 10.0;
        }
    }

    // Mild bonus for using bins with below-average residual (reduces spread).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;

    // Dead-space avoidance scaled to what's actually usable next.
    let min_useful = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        score += (min_useful - post_residual) as f64 * 6.0;
        if post_residual <= 5 {
            score += 25.0;
        }
        if post_residual < min_useful / 2 {
            score += (min_useful / 2 - post_residual) as f64 * 4.0;
        }
    }

    // Tight fit reward: quadratic near-full bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.80 {
        score -= (fit_ratio - 0.80) * (fit_ratio - 0.80) * 90.0;
    }
    if fit_ratio > 0.97 {
        score -= 14.0;
        if post_residual == 0 {
            score -= 6.0;
        }
    }
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: prefer using the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
        let leftover = bin_residual - item_size;
        if leftover <= 5 { score -= 8.0; }
        if next_item_size > 0 && leftover > next_item_size && leftover - next_item_size < 8 {
            score += 7.0;
        }
    }
    if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fragmentation = mean_residual / cap;

    // Residual "primed" relative to next item.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let gap = bin_residual as i64 - next_item_size as i64;
        if gap >= 0 && gap < 12 {
            score -= 8.0 - gap as f64 * 0.5;
        } else if gap < 0 && (-gap) < next_item_size as i64 {
            score += (-gap) as f64 * 0.30;
        }
    }

    if bin_residual != bin_capacity {
        score -= pressure;
        if progress < 0.3 && fragmentation < 0.15 {
            score -= (bin_residual as f64 / cap) * 3.0;
        }
        // Deep-fill bias — bins whose residual is already small are the
        // ones closest to closure; tilt harder as residual shrinks.
        let res_ratio = bin_residual as f64 / cap;
        if res_ratio < 0.25 {
            score -= (0.25 - res_ratio) * 14.0;
        }
        // NEW: closure velocity — reward bins whose residual is already below
        // the typical item size, pushing them to exact closure rather than
        // letting them linger as fragmented half-full bins.
        if next_item_size > 0 && bin_residual <= next_item_size {
            score -= (next_item_size - bin_residual + 1) as f64 * 0.8;
        }
    } else {
        // New-bin candidate: penalize, more so late in the stream.
        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if next_item_size as f64 > cap * 0.6 {
            score -= 6.0;
        }
        if mean_residual > cap * 0.35 {
            score -= 4.0;
        }
        if post_residual > 0 && post_residual <= 8 {
            score -= 5.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 12.0;
        }
        if fragmentation < 0.12 && progress > 0.1 {
            score += 4.0;
        }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if next_item_size > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= next_item_size {
                let after = fresh_post - next_item_size;
                if after == 0 {
                    score -= 18.0;
                } else if after <= next_item_size / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
                // NEW: triple-completion — fresh bin that can absorb the next
                // item AND still leave room for a third small item.
                if after >= next_item_size && next_item_size <= 20 {
                    score -= 2.5;
                }
            }
        }
        // Fragmented open bins make a fresh bin attractive.
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
        // NEW: exact-fill detection — if the fresh bin's leftover matches a
        // plausible small item slot (common in integer streams), favor it.
        if post_residual > 0 && post_residual <= 15 && fitting_bins_count > 0 {
            score -= 3.0;
        }
