    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 10.0;
    }
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 14.0 + (item_size as f64 / cap) * 4.0;
    }

    // Three-item chain potential.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next > 0 && after_next <= 12 {
            score -= 5.0;
        }
        if after_next >= next_item_size + next_item_size / 2 && after_next <= 2 * next_item_size {
            score -= 3.0;
        }
        if next_item_size >= 3 && next_item_size <= 12 && after_next % next_item_size == 0 {
            score -= 3.5;
        }
        // NEW: divisibility cascade — residuals that divide cleanly by the
        // next item size promise multi-item chains; deepen the reward.
        if next_item_size >= 2 && post_residual % next_item_size == 0 {
            score -= 4.0;
        }
    }

    // Quadratic waste penalty for large leftovers.
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap;
        if waste_ratio > 0.5 {
            score += (waste_ratio - 0.5) * (waste_ratio - 0.5) * 40.0 + (waste_ratio - 0.5) * 10.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
        // Escalating terminal-waste penalty — dead space below smallest items.
        if post_residual <= 3 && next_item_size > post_residual {
            score += 12.0;
        }
        // Mid-band dead zone — residuals that neither fit the next item
        // nor are near-zero are the main source of wasted bins; penalize the
        // band (just below next_item_size) proportionally to next item size.
        if next_item_size > 4 && post_residual < next_item_size && post_residual > 3 {
            score += (next_item_size - post_residual) as f64 * 0.55;
        }
        // NEW: awkward-window penalty — post residuals in the 16–30 band are
        // too small for most items yet too large to ignore; discourage them
        // unless the next item actually fits.
        let band_lo = 16u32;
        let band_hi = 30u32;
        if post_residual >= band_lo && post_residual <= band_hi
            && (next_item_size == 0 || next_item_size > post_residual) {
            score += 6.0 + (post_residual as f64 - band_lo as f64) * 0.25;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin's leftover exactly hosts the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Leftover can host next item; reward closeness of the chain fit.
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - chain_waste / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit in leftover; penalize proportionally to how much it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += 0.5 * miss;
    }

    // Reward tight fits relative to mean residual across open bins.
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist and it's early/mid stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        let pressure = open_bins_count as f64 / (1.0 + progress);
        score += 30.0 + pressure;
        // But allow a new bin if even the best chain fit is bad.
        if next_item_size > 0 && post_residual > next_item_size {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Small bonus for filling bins nearly completely (small absolute residual).
    score -= 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

