        }
        if n > 0 && pr >= 1 && pr <= 3 && n == pr {
            score -= 10.0;
        }
        if n > 0 && pr >= n && pr - n <= 1 {
            score -= 9.0;
        }
    } else if pr < 28 {
        let d = (28 - pr) as f64;
        score += 11.0 + d * (1.0 + 0.03 * d);
        if n >= 12 && n <= pr {
            score -= 18.0;
        }
        if n >= 8 && pr >= 2 * n {
            score -= 9.0;
        }
        if n > 0 && pr >= n && (pr - n) < 4 {
            score -= 4.0;
        }
    } else {
        if pr % 5 == 0 { score -= 5.5; }
        if pr % 10 == 0 { score -= 4.5; }
        if pr % 25 == 0 { score -= 3.5; }
        if n > 0 && pr > n && pr - n <= 10 {
            score -= 4.5;
        }
        if n >= 10 {
            let r = pr % n;
            if r > 0 && n - r <= 4 {
                score -= 3.0;
            }
        }
        if n >= 15 && pr >= n + n / 2 {
            score -= 2.5;
        }
        if n > pr && pr > 28 && pr < 45 {
            score += 3.5;
        }
    }

    // Two-step lookahead: chain fits strongly rewarded.
    if n > 0 {
        if n == pr {
            score -= 52.0;
        } else if n < pr {
            let npr = pr - n;
            if npr < 12 { score -= 15.0; }
            if npr % 10 == 0 { score -= 5.0; }
            if npr % 25 == 0 { score -= 3.5; }
            if npr >= n && npr < 40 { score -= 2.5; }
            if npr >= 20 { score -= 4.0; }
            if n >= 6 && npr >= 2 * n {
                score -= 3.5 + (npr / n.max(1)) as f64;
            }
            if npr > 15 && npr < 25 && npr % 5 != 0 {
                score += 2.5;
            }
        } else {
            let shortfall = n - pr;
            score += 12.0 + shortfall as f64 * 0.06;
            if shortfall <= 4 { score -= 6.0; }
        }
    } else {
        score -= 8.0;
    }

    // Tightness scaled by fill ratio, with quadratic near-perfect fit bonus.
    let fill_ratio = 1.0 - bin_residual as f64 / cap;
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += tightness * (7.0 + 7.0 * fill_ratio);
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.80 {
        score -= (fit_ratio - 0.80) * (fit_ratio - 0.80) * 90.0;
    }
    if fit_ratio > 0.97 {
        score -= 14.0;
        if pr == 0 { score -= 6.0; }
    }

    // Deviation from mean residual: nearly-full bins preferred (convex tilt).
    let dev = mean_residual - pr as f64;
    score += (pr as f64 - mean_residual) * 0.40;
    if dev > 0.0 {
        score -= dev * 0.05;
    }

    // Deep-fill bias: bins with small residual are closest to closure.
    if bin_residual != bin_capacity {
        let res_ratio = bin_residual as f64 / cap;
        if res_ratio < 0.25 {
            score -= (0.25 - res_ratio) * 14.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity && bin_residual >= item_size {
        score -= 34.0;
        if bin_residual - item_size <= 5 { score -= 10.0; }
        if n > 0 && bin_residual - item_size >= n {
            score -= 6.0;
        }
        let leftover = bin_residual - item_size;
        if n > 0 && leftover > n && leftover - n < 8 && leftover > 30 {
            score += 9.0;
        }
        if leftover == 0 { score -= 6.0; }
    }
    if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 7.5;
    }

    // New-bin candidate.
    if bin_residual == bin_capacity {
        score += 37.0 + fragmentation * 24.0 - progress * 7.0;
        if item_size > 55 {
            score -= 13.0 + (item_size - 55) as f64 * 0.30;
        }
        if n >= 55 {
            score += 16.0;
        }
        if open_bins_count < 3 {
            score -= 10.0;
        }
        if fragmentation > 0.45 && item_size < 40 {
            score += 7.0;
        }
        if n > 0 && item_size < bin_residual && bin_residual - item_size == n {
            score += 22.0;
        }
        if item_size < 25 && mean_residual > item_size as f64 * 2.0 {
            score += 6.0;
        }
        if progress > 0.65 {
            score += 8.0 + (progress - 0.65) * 34.0;
        }
        if progress >= 0.25 && progress <= 0.65 && item_size <= 45 {
            score += (45 - item_size) as f64 * 0.22 * (1.0 - fragmentation).max(0.0);
        }
        if fitting_bins_count >= 4 && item_size < 35 {
            score -= 5.0;
        }
        if n > 20 && mean_residual < n as f64 * 0.8 {
            score -= 6.0;
        }
        if n > 0 && item_size <= bin_capacity - n && bin_capacity - item_size == n {
            score -= 12.0;
        }
        if n > 0 && pr % 10 == 0 && pr <= n {
            score += 9.0;
        }
        if fitting_bins_count == 0 {
            score -= 14.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if n > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= n {
                let after = fresh_post - n;
                if after == 0 {
                    score -= 18.0;
                } else if after <= n / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
            }
        }
        // Fragmented open bins make a fresh bin attractive.
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
    }

    // Mid-band dead zone: residuals just below next item size are prime waste.
    if pr > 0 && n > 4 && pr < n && pr > 3 {
        score += (n - pr) as f64 * 0.55;
    }
    if pr <= 3 && n > pr {
        score += 12.0;
    }

    // Quadratic waste penalty for large leftovers.
    if pr > 0 {
        let waste_ratio = pr as f64 / cap;
        if waste_ratio > 0.5 {
            score += (waste_ratio - 0.5) * (waste_ratio - 0.5) * 40.0 + (waste_ratio - 0.5) * 10.0;
        }
    }

    // Mild open-bin pressure (logarithmic to avoid runaway spreading).
    score += (open_bins_count as f64).ln().max(0.0) * 2.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let dead = (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
        score += 0.8 * dead;
    }

    // Perfect closure bonus: filling a bin exactly is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_waste = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + next_waste);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Remaining sliver cannot host the next item: penalize proportionally.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Scarcity pressure: many open bins relative to progress -> consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (1.0 + 50.0 * (1.0 - progress).max(0.05));
    score += 0.15 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Global residual alignment: prefer bins close to mean residual (keeps fleet uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: only attractive when the item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let poor_fits = fitting_bins_count == 0 || (post_residual as f64) > 40.0;
        if poor_fits && item_frac > 0.5 {
            score -= 30.0 * item_frac;
        } else {
            score += 45.0 + 20.0 * (1.0 - item_frac);
        }
    }

    // Late-stream: slightly prefer reusing bins to wrap up.
    if progress > 0.8 && bin_residual < bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
