        score -= 60.0;
    }

    // Modulo arithmetic on post_residual: residuals near multiples of common
    // small item sizes (10..20) are reusable "harmonics" of the capacity.
    let harmonic = post_residual % 25;
    if harmonic <= 5 {
        score -= 12.0; // residual aligns with a small future item class
    } else if harmonic >= 20 {
        score -= 6.0;
    }

    // Penalize dead-space zones: residuals in (10, 20) are hard to fill
    // since smallest items are ~1..10 but mid items dominate.
    if post_residual > 10 && post_residual < 20 {
        score += 8.0;
    }
    // Very small unusable slivers are dead space too.
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    // Lookahead coupling: reward residuals that exactly fit the next item,
    // penalize leaving a residual that neither fits next item nor is tiny.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 5.0; // next item cannot use this bin's leftover
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item is large and no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        // New bin: post_residual = capacity - item_size.
        let tightness = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for very large items (little waste potential),
        // discourage otherwise by adding a fixed opening cost.
        score += 30.0 - 45.0 * tightness;
        if next_item_size > 0 && post_residual as i64 - next_item_size as i64 >= 0 {
            score -= 15.0; // new bin can also host the next item
        }
    } else {
        // Existing bins get a mild preference bonus scaled by stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 + 5.0 * progress;
    }

    // Coupling with mean residual: if this bin's residual is far below mean,
    // it is nearly full -> good to fill it (reward), else mild penalty.
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64 / (open_bins_count as f64 + 10.0);

    score
}

