        score -= 40.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidation into existing bins,
    // penalize opening new bins proportionally.
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable only if it leaves a large, reusable gap.
        score += 15.0 + 3.0 * open_bins_count as f64;
        if post_residual >= 50 {
            score -= 20.0;
        }
        // Early in the stream, opening bins is cheap and useful.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    } else {
        // Reward using bins whose residual deviates from the mean (harvest odd gaps).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 0.15 * dev;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement sets up a chain; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual - next_item_size < 10 {
            score -= 12.0;
        }
    }
    // If next item cannot use the leftover at all and leftover is tiny, extra penalty.
    if next_item_size > post_residual && post_residual < 10 {
        score += 15.0;
    }

    score
}

