        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if n as f64 > cap * 0.6 {
            score -= 6.0;
        }
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if n > 0 && bin_capacity - item_size == n {
            score -= 12.0;
        }
        if fragmentation < 0.12 && progress > 0.1 {
            score += 4.0;
        }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if n > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= n {
                let after = fresh_post - n;
                if after == 0 {
                    score -= 18.0;
                } else if after <= n / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
            }
        }
        if pr > 0 && pr <= 8 {
            score -= 5.0;
        }
        // NEW: opening a fresh bin is acceptable when the new bin would be
        // nearly closed by the next item (pair completion), but only early.
        if n > 0 && progress < 0.5 && bin_capacity.saturating_sub(item_size) >= n {
            let after = bin_capacity - item_size - n;
            if after == 0 {
                score -= 10.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
