            // Next item also fits here: reward proportional to tightness
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item won't fit: penalize based on wasted potential
            score += 8.0 * (diff / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins whose post_residual deviates favorably
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (post_f - mean_residual) / mean_residual;
        if rel < 0.0 {
            // Below-mean residual = tighter packing, good
            score -= 10.0 * (-rel);
        } else {
            // Above-mean residual = loose packing, bad
            score += 6.0 * rel;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // Base penalty so new bins are opened only when justified
        score += 35.0;
        // If item is large relative to capacity, a fresh bin is more attractive
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
