            score += (next_item_size - post_residual) as f64 * 0.35;
        }
        // Escalating terminal-waste penalty — dead space below smallest items.
        if post_residual <= 3 && next_item_size > post_residual {
            score += 12.0;
        }
        // Mid-band dead zone — residuals that neither fit the next item
        // nor are near-zero are the main source of wasted bins.
        if next_item_size > 4 && post_residual < next_item_size && post_residual > 3 {
            score += (next_item_size - post_residual) as f64 * 0.55;
        }
        // NEW: large-residual softening — when many bins are open and the
        // post residual is still roomy, mild waste is acceptable; reduce
        // the flat post_residual term to avoid scattering across bins.
        if open_bins_count > 4 && waste_ratio > 0.35 {
            score -= (waste_ratio - 0.35) * 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: squared residual normalized by capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: penalize bins whose leftover cannot host the next item,
    // but reward leftovers that exactly accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: strongly prefer fullest packing.
        score -= 40.0 * (1.0 - fit_ratio);
    }

    // Last-chance bin: if this is the only bin that fits, discourage
    // opening a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in the stream, be conservative with new bins;
    // late in the stream, allow opening fresh bins to consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: cost grows with number of open bins and
        // shrinks as the stream progresses.
        score = 60.0 + 3.0 * open_bins_count as f64 * (1.0 - progress);
        // Opening a bin is attractive if the item is huge (hard to place later).
        score -= 0.5 * item_size as f64;
        // If mean residual across open bins is tiny, open bins are nearly
        // exhausted anyway; a fresh bin is natural.
        score += mean_residual * 0.3;
        // But if this bin is the only fit and the item is large, keep old bins.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Existing bins: slight preference for bins below mean residual
        // (keeps a spread of useful gaps).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
        // Many open bins: prefer consolidating into existing space.
        if open_bins_count > 4 {
            score -= 2.0 * (open_bins_count.min(20) as f64) * 0.1;
        }
    }

    // Dead-space penalty: residuals too small for the smallest plausible
    // future item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
