    let norm_pr = pr / cap;

    // Base: wasted space after placement, non-linearly penalized
    let mut score = norm_pr * norm_pr * 120.0 + norm_pr * 60.0;

    // Smooth coupling: residual waste matters more as stream progresses
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score *= progress_weight;

    // Reward tight fits (small post_residual) with smooth decay
    let tightness = (-norm_pr * 8.0).exp();
    score -= tightness * 45.0;

    // Penalize bins whose residual diverges from mean residual (smooth)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 30.0;

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 {
        score -= 80.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = next_item_size as f64 / cap;
        score -= 25.0 * (1.0 - next_fit);
    } else if next_item_size > post_residual {
        // smooth penalty proportional to mismatch
        let gap = (next_item_size as f64 - pr) / cap;
        score += gap * gap * 20.0;
    }

    // Mild penalty for proliferating bins relative to progress
    score += open_bins_count as f64 * (0.5 + progress) * 0.8;

    // New-bin candidate: neutral-ish baseline, slightly worse early
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

