        if pr < min_useful / 2 {
            score += (min_useful / 2 - pr) as f64 * 4.0;
        }
        // Sharper mid-band dead-zone: residuals that neither fit the next item
        // nor are near-zero are the main source of wasted bins.
        if n > 4 && pr > 3 && pr < n {
            score += (n - pr) as f64 * 0.55;
        }
        if pr <= 3 && n > pr {
            score += 12.0;
        }
    }

    // Quadratic waste penalty for large leftovers.
    if pr > 0 {
        let waste_ratio = pr as f64 / cap;
        if waste_ratio > 0.5 {
            score += (waste_ratio - 0.5) * (waste_ratio - 0.5) * 40.0 + (waste_ratio - 0.5) * 10.0;
        }
        if n > 0 && pr < n {
            score += (n - pr) as f64 * 0.35;
        }
    }

    // Tight fit reward: quadratic near-full bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.80 {
        score -= (fit_ratio - 0.80) * (fit_ratio - 0.80) * 90.0;
    }
    if fit_ratio > 0.97 {
        score -= 14.0;
        if pr == 0 {
            score -= 6.0;
        }
    }
    if pr == 0 {
        score -= 30.0;
    }

    // Two-step lookahead: chain fits strongly rewarded.
    if n > 0 {
        if n == pr {
            score -= 52.0;
        } else if n < pr {
            let npr = pr - n;
            if npr < 12 { score -= 15.0; }
            if npr % 10 == 0 { score -= 5.0; }
            if npr % 25 == 0 { score -= 3.5; }
            if npr >= n && npr < 40 { score -= 2.5; }
            if npr >= 20 { score -= 4.0; }
            if n >= 6 && npr >= 2 * n {
                score -= 3.5 + (npr / n.max(1)) as f64;
            }
            if npr > 15 && npr < 25 && npr % 5 != 0 {
                score += 2.5;
            }
            if npr > 0 && npr <= 12 {
                score -= 5.0;
            }
            // Triple-chain lookahead.
            if npr >= n + n / 2 && npr <= 2 * n {
                score -= 3.0;
            }
        } else {
            let shortfall = n - pr;
            score += 12.0 + shortfall as f64 * 0.06;
            if shortfall <= 4 { score -= 6.0; }
        }
    } else {
        score -= 8.0;
    }

    // Tightness scaled by fill ratio.
    let fill_ratio = 1.0 - bin_residual as f64 / cap;
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += tightness * (7.0 + 7.0 * fill_ratio);

    // Deviation from mean residual: nearly-full bins preferred.
    score += (pr as f64 - mean_residual) * 0.40;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity && bin_residual >= item_size {
        score -= 34.0;
        if bin_residual - item_size <= 5 { score -= 10.0; }
        if n > 0 && bin_residual - item_size >= n {
            score -= 6.0;
        }
        let leftover = bin_residual - item_size;
        if n > 0 && leftover > n && leftover - n < 8 && leftover > 30 {
            score += 9.0;
        }
        if leftover == 0 { score -= 6.0; }
    }
    if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 7.5;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        score += 37.0 + fragmentation * 24.0 - progress * 7.0;
        if item_size > 55 {
            score -= 13.0 + (item_size - 55) as f64 * 0.30;
        }
        if n >= 55 {
            score += 16.0;
        }
        if open_bins_count < 3 {
            score -= 10.0;
        }
        if fragmentation > 0.45 && item_size < 40 {
            score += 7.0;
        }
        if n > 0 && item_size < bin_residual && bin_residual - item_size == n {
            score += 22.0;
        }
        if item_size < 25 && mean_residual > item_size as f64 * 2.0 {
            score += 6.0;
        }
        if progress > 0.65 {
            score += 8.0 + (progress - 0.65) * 34.0;
        }
        if progress >= 0.25 && progress <= 0.65 && item_size <= 45 {
            score += (45 - item_size) as f64 * 0.22 * (1.0 - fragmentation).max(0.0);
        }
        if fitting_bins_count >= 4 && item_size < 35 {
            score -= 5.0;
        }
        if n > 20 && mean_residual < n as f64 * 0.8 {
            score -= 6.0;
        }
        if n > 0 && item_size <= bin_capacity - n && bin_capacity - item_size == n {
            score -= 12.0;
        }
        if n > 0 && pr % 10 == 0 && pr <= n {
            score += 9.0;
        }
        if pr > 0 && pr <= 8 {
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if fragmentation < 0.12 && progress > 0.1 {
            score += 4.0;
        }
        // NEW: pair-completion lookahead in a fresh bin — a fresh bin whose
        // post residual exactly matches the next item is a strong split.
        if n > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= n {
                let after = fresh_post - n;
                if after == 0 {
                    score -= 18.0;
                } else if after <= n / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
            }
        }
        // NEW: fragmented open bins make a fresh bin genuinely attractive.
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
    } else {
        // Deep-fill bias: bins with small residuals are closest to closure.
        let res_ratio = bin_residual as f64 / cap;
        if res_ratio < 0.25 {
            score -= (0.25 - res_ratio) * 14.0;
        }
        // Residual "primed" relative to next item.
        if n > 0 {
            let gap = bin_residual as i64 - n as i64;
            if gap >= 0 && gap < 12 {
                score -= 8.0 - gap as f64 * 0.5;
            } else if gap < 0 {
                score += (-gap) as f64 * 0.30;
            }
        }
    }

    // Mild open-bin pressure to discourage needless spreading.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Harmonic class of post_residual: dead space classes matter.
    // Residuals in [1..10] are "near-dead" unless exactly reusable.
    let dead = (post_residual as f64) * (post_residual as f64);
    score += dead * 0.3;

    // Lookahead: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 250.0 - (slack as f64) * 10.0;
            } else {
                score -= (post_residual - next_item_size) as f64 * 2.0;
            }
        } else {
            // next item cannot fit here; penalize large residuals that
            // will be stranded anyway.
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: opening a new bin should only win
    // when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = (bin_capacity as f64) * 0.9 + (open_bins_count as f64);
        // If current item leaves a nice residual in a fresh bin,
        // make it attractive (e.g., item <= 50 leaving >= 50).
        if item_size <= bin_capacity / 2 {
            score -= 60.0;
        }
        // Late in the stream, prefer closing out open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 40.0;
        // If mean residual of open bins is large, opening new bin is wasteful.
        score += mean_residual * 0.5;
    } else {
        // Favor bins whose residual is much larger than mean (use the roomy ones).
        score -= (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Modulo/harmonic structure: residuals divisible by common item
    // sizes (10, 20, 25, 50) are more reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 30.0;
        }
        if post_residual % 25 == 0 {
            score -= 20.0;
        }
        if post_residual % 50 == 0 {
            score -= 40.0;
        }
        // Penalize odd residuals slightly (harder to pair with even items).
        if post_residual % 2 == 1 {
            score += 8.0;
        }
    }

    // Small penalty for spreading across many bins when plenty fit.
    if fitting_bins_count > 3 {
        score += 5.0;
    }

    score
}

