pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..=100,
    // but small gaps are nearly unusable) can ever fill are heavily penalized.
    if post_residual > 0 {
        // Dead-space severity grows super-linearly for tiny gaps.
        let gap = post_residual as f64;
        if post_residual < 10 {
            score += 40.0 + (10.0 - gap) * 6.0; // nearly unusable sliver
        } else if post_residual < 25 {
            score += 12.0 + (25.0 - gap) * 1.5;
        }
        // Bonus if the gap can still hold the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0 + (next_item_size as f64) * 0.2;
        } else if next_item_size > 0 {
            score += 10.0; // lookahead cannot use this gap
        }
    } else {
        // Perfect fit: strongly reward closing the bin.
        score -= 25.0;
    }

    // Tight fit reward relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than spreading out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if mean_residual > 35.0 || fragmentation < 5.0 {
            score += 30.0; // keep using open bins when they're still roomy
        } else {
            score -= 5.0; // existing bins too fragmented, fresh bin OK
        }
    }

    // Mild preference for bins below average residual (fill emptier-first balance).
    score += ((bin_residual as f64 - mean_residual) * 0.05).max(-5.0).min(5.0);

    score
}

