        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= dev * 0.10;
        }
    } else {
        // New-bin candidate: penalize, more so late in the stream.
        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if n as f64 > cap * 0.6 {
            score -= 6.0;
        }
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if n > 0 && bin_capacity - item_size == n {
            score -= 12.0;
        }
        if fragmentation < 0.12 && progress > 0.1 {
            score += 4.0;
        }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if n > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= n {
                let after = fresh_post - n;
                if after == 0 {
                    score -= 18.0;
                } else if after <= n / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
                // Triple-completion potential in a fresh bin.
                if after >= n && after - n < 8 {
                    score -= 5.0;
                }
                // NEW: exact pair-split — fresh bin sized so the next item
                // leaves a residual equal to a common small item slot.
                if after % 3 == 0 && after > 0 && after <= 30 {
                    score -= 2.0;
                }
            } else if n <= bin_capacity {
                score += 4.0;
            }
        }
        // NEW: if the current item is large and no open bin fits it well,
        // a fresh bin is fine; but when many bins are near closure, resist.
        if open_bins_count > 2 && fragmentation < 0.20 {
            score += 5.0;
        }
        if pr > 0 && pr <= 8 {
            score -= 5.0;
        }
    }

    score
}

