    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 8.0; // tiny unusable slivers
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item still fits here: mild reward proportional to fit tightness
            let nl = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * nl;
        } else {
            // next item won't fit here: penalize bins that would strand the lookahead
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // existing fits are poor or the item is small relative to abundant space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses
        // (early on, cheap; late, prefer consolidation).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 35.0 + 25.0 * progress;

        // If many bins are open and mean residual is large, opening new bins is wasteful.
        score += 0.15 * open_bins_count as f64;
        score += 0.10 * mean_residual;

        // Small items should almost never open a new bin.
        if item_size < 30 {
            score += 30.0;
        }
        // Large items with no good existing home may justify a new bin.
        if item_size > 60 && fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Existing bin: slight preference when its residual is below average
        // (consolidate into tighter bins, keep loose bins for future items).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Prefer filling nearly-full bins completely to close them out.
    if bin_residual - item_size == 0 {
        score -= 50.0;
    }

    score
}

