pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 + 2.0 * progress);
    score -= 12.0 * poly;

    // Tight fits are exponentially attractive, more so late in the stream
    score -= 8.0 * (-(x * x) / (0.02 + 0.05 * (1.0 - progress))) * 0.01;

    // Penalize waste relative to mean residual state
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    // Last-chance bin bonus (smoothed)
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - x) * (1.0 + progress);
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 4.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    // Congestion: prefer consolidating into existing bins when many are open
    score += 0.05 * open_bins_count as f64 * x;

    // Slight bias toward opening new bins early (when little invested)
    if bin_residual == bin_capacity {
        score += 1.0 - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;

    // Dead-space avoidance scaled to what's actually usable next.
    let min_useful = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        score += (min_useful - post_residual) as f64 * 6.0;
        if post_residual <= 5 {
            score += 25.0;
        }
        if post_residual < min_useful / 2 {
            score += (min_useful / 2 - post_residual) as f64 * 4.0;
        }
    }

    // Tight fit reward: quadratic near-full bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.80 {
        score -= (fit_ratio - 0.80) * (fit_ratio - 0.80) * 90.0;
    }
    if fit_ratio > 0.97 {
        score -= 14.0;
        if post_residual == 0 {
            score -= 6.0;
        }
    }
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: prefer using the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
        let leftover = bin_residual - item_size;
        if leftover <= 5 { score -= 8.0; }
        if next_item_size > 0 && leftover > next_item_size && leftover - next_item_size < 8 {
            score += 7.0;
        }
    }
    if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fragmentation = mean_residual / cap;

    // Residual "primed" relative to next item.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let gap = bin_residual as i64 - next_item_size as i64;
        if gap >= 0 && gap < 12 {
            score -= 8.0 - gap as f64 * 0.5;
        } else if gap < 0 && (-gap) < next_item_size as i64 {
            score += (-gap) as f64 * 0.30;
        }
    }

    if bin_residual != bin_capacity {
        score -= pressure;
        if progress < 0.3 && fragmentation < 0.15 {
            score -= (bin_residual as f64 / cap) * 3.0;
        }
        // Deep-fill bias — bins whose residual is already small are the
        // ones closest to closure; tilt harder as residual shrinks.
        let res_ratio = bin_residual as f64 / cap;
        if res_ratio < 0.25 {
            score -= (0.25 - res_ratio) * 14.0;
        }
        // NEW: closure-distance bias — prefer bins whose residual is an
        // exact multiple of the next item, enabling chain fills.
        if next_item_size > 0 && bin_residual % next_item_size == 0 {
            score -= 3.0;
        }
    } else {
        // New-bin candidate: penalize, more so late in the stream.
        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if next_item_size as f64 > cap * 0.6 {
            score -= 6.0;
        }
        if mean_residual > cap * 0.35 {
            score -= 4.0;
        }
        if post_residual > 0 && post_residual <= 8 {
            score -= 5.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 12.0;
        }
        if fragmentation < 0.12 && progress > 0.1 {
            score += 4.0;
        }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if next_item_size > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= next_item_size {
                let after = fresh_post - next_item_size;
                if after == 0 {
                    score -= 18.0;
                } else if after <= next_item_size / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
            }
        }
        // Fragmented open bins make a fresh bin attractive.
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
    }

    // Prefer bins whose residual is below average, with convex tilt.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= dev * 0.20;
        if dev > 0.0 {
            score -= dev * 0.05;
        }
    }

    // Lookahead: reward when next item fits snugly in post residual.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 10.0;
    }
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 14.0 + (item_size as f64 / cap) * 4.0;
    }

    // Three-item chain potential.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next > 0 && after_next <= 12 {
            score -= 5.0;
        }
        if after_next >= next_item_size + next_item_size / 2 && after_next <= 2 * next_item_size {
            score -= 3.0;
        }
        if next_item_size >= 3 && next_item_size <= 12 && after_next % next_item_size == 0 {
            score -= 3.5;
        }
    }

    // Quadratic waste penalty for large leftovers.
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap;
        if waste_ratio > 0.5 {
            score += (waste_ratio - 0.5) * (waste_ratio - 0.5) * 40.0 + (waste_ratio - 0.5) * 10.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
        // Escalating terminal-waste penalty — dead space below smallest items.
        if post_residual <= 3 && next_item_size > post_residual {
            score += 12.0;
        }
        // Mid-band dead zone — residuals that neither fit the next item
        // nor are near-zero are the main source of wasted bins.
        if next_item_size > 4 && post_residual < next_item_size && post_residual > 3 {
            score += (next_item_size - post_residual) as f64 * 0.55;
        }
        // NEW: two-step lookahead — if the item AFTER next can also chain
        // into the post residual, reward the fit; otherwise penalize
        // residuals that strand both upcoming items.
        if next_item_size > 0 {
            let r = post_residual as i64 - next_item_size as i64;
            if r > 0 {
                // Approximate the item-after size as the mean of the stream
                // (next_item_size as proxy); reward a residual that could
                // still absorb another comparable item.
                if (r as u32) >= next_item_size && (r as u32) <= next_item_size * 2 {
                    score -= 2.5;
                }
            } else if r > -(next_item_size as i64) / 2 {
                score += 2.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible into useful chunks
    // are worth more (reward by subtracting), awkward residuals penalized.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward.
        score -= 200.0;
    } else {
        // Harmonic divisibility ladder: residual that can exactly host
        // common item sizes (multiples of 5/10/20/25/50) is reusable.
        let mut bonus = 0.0;
        if pr % 5 == 0 { bonus += 4.0; }
        if pr % 10 == 0 { bonus += 6.0; }
        if pr % 20 == 0 { bonus += 6.0; }
        if pr % 25 == 0 { bonus += 5.0; }
        if pr % 50 == 0 { bonus += 8.0; }
        score -= bonus;

        // Dead-space penalty: tiny unusable residuals.
        if pr < 10 {
            score += (10 - pr) as f64 * 8.0;
        }

        // Harmonic class via integer division thresholds: residual in a
        // "mid band" (neither tiny nor large) is least flexible.
        let band = pr / 10; // 0..10
        match band {
            0 => score += 30.0,          // 1..9: nearly dead
            1 | 2 => score += 12.0,      // 10..29: only small items fit
            3 | 4 | 5 => score += 20.0,  // 30..59: mid band, awkward
            6 | 7 => score += 5.0,       // 60..79: decent
            _ => score -= 10.0,          // 80..99: very reusable
        }

        // Lookahead coupling: if next item fits exactly into post_residual,
        // big reward (harmonic chaining).
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 120.0;
            } else if next_item_size <= pr {
                // next fits: residual class compatibility
                let nxt = next_item_size;
                if pr % nxt == 0 {
                    score -= 40.0;
                }
                score -= (pr - nxt) as f64 * 0.3;
            } else {
                // next item won't fit here: penalize slightly more if this
                // residual is small anyway (dead end trajectory).
                if pr < next_item_size && pr < 20 {
                    score += 15.0;
                }
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only
    // open when no open bin offers a good harmonic fit.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in the stream, opening bins is cheaper (builds a pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 25.0;
        // If nothing fits well elsewhere (large mean residual mismatch),
        // opening is more attractive.
        if mean_residual < item_size as f64 {
            score -= 30.0;
        }
    } else {
        // Prefer tighter existing bins: small bin_residual relative to item.
        score += (bin_residual as f64 - item_size as f64) * 0.15;
        // Crowding: many open bins -> prefer consolidating into existing ones.
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
        // Prefer bins whose residual is below average (they'd waste more).
        if (bin_residual as f64) > mean_residual {
            score += 6.0;
        } else {
            score -= 4.0;
        }
    }

    // Mild tie-break on fill ratio (waste minimization).
    score -= (item_size as f64 / cap) * 10.0;

    score
}

