        // common item size band (5..15) that the stream is likely to produce.
        if pr >= 4 && pr < 15 && n > 0 && (pr + 1..=pr + 3).contains(&n) {
            score += 3.0;
        }
    } else {
        // New-bin candidate: penalize, more so late in the stream.
        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if n as f64 > cap * 0.6 {
            score -= 6.0;
        }
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if n > 0 && bin_capacity - item_size == n {
            score -= 12.0;
        }
        if fragmentation < 0.12 && progress > 0.1 {
            score += 4.0;
        }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if n > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= n {
                let after = fresh_post - n;
                if after == 0 {
                    score -= 18.0;
                } else if after <= n / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
                // Triple-completion potential in a fresh bin.
                if after >= n && after - n < 8 {
                    score -= 5.0;
                }
            } else if n <= bin_capacity {
                score += 4.0;
            }
        }
        if pr > 0 && pr <= 8 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A residual is "unusable" if it's too small for typical future items
    // (assume items >= 10 in classic case, but sizes 1..100 unknown; use
    // next_item_size as a proxy for what we must still fit).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space relative to the known next item.
            score += 15.0 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins that can also host the next item (good chaining).
            score -= 8.0;
        }
    }

    // Non-linear penalty on small post_residual (classic wasted-space curve).
    if post_residual > 0 && post_residual < 25 {
        score += (25 - post_residual) as f64 * 2.5;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open bins pressure: discourage opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += open_bins_count as f64 * 4.0;
