pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: post_residual == 0 is ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // chain of perfect fits
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= (10.0 - slack * 0.3).max(-15.0); // next item fits: mild reward, decays with slack
        } else {
            // next item won't fit: penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += (over * 0.15).min(20.0);
        }
    } else {
        // last item: strongly prefer zero waste
        score += post_residual as f64 * 0.5;
    }

    // Compare post_residual to mean residual: penalize leaving this bin far above mean
    // (unbalanced residuals), reward pulling residuals toward the mean.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += (pr - mean_residual).abs() * 0.08;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Tightness of current fit: reward filling a large fraction of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 8.0;

    // Penalize opening new bins when many bins are open with room
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty grows with open bins and mean residual
        score += 15.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.1;
        // but if no open bin fits well (post_residual small relative to capacity), new bin is fine
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Small penalty for creating tiny unusable residuals (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

