        if post_residual <= 3 && next_item_size > post_residual {
            score += 12.0;
        }
        // Mid-band dead zone: residuals that neither fit the next item nor are
        // near-zero are the main source of wasted bins; penalize the band
        // (just below next_item_size) proportionally, stronger for large next items.
        if next_item_size > 4 && post_residual < next_item_size && post_residual > 3 {
            score += (next_item_size - post_residual) as f64 * (0.55 + (next_item_size as f64 / 100.0) * 0.25);
