pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity.max(1) as f64;
    let n = next_item_size;

    // Dead-space avoidance scaled to what's actually usable next.
    let min_useful = if n > 0 { n.min(80) } else { 10 };
    if pr > 0 && pr < min_useful {
        score += (min_useful - pr) as f64 * 6.0;
        if pr <= 5 { score += 25.0; }
        if pr < min_useful / 2 { score += (min_useful / 2 - pr) as f64 * 4.0; }
        if n > 4 && pr > 3 { score += (n - pr) as f64 * 0.55; }
        if pr <= 3 && n > pr { score += 12.0; }
    }

    // Perfect closure.
    if pr == 0 { score -= 30.0; }

    // Tight fit reward: quadratic near-full bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.80 {
        score -= (fit_ratio - 0.80) * (fit_ratio - 0.80) * 90.0;
    }
    if fit_ratio > 0.97 {
        score -= 14.0;
        if pr == 0 { score -= 6.0; }
    }

    // Quadratic waste penalty for large leftovers + mid-band dead zone.
    if pr > 0 {
        let waste_ratio = pr as f64 / cap;
        if waste_ratio > 0.5 {
            score += (waste_ratio - 0.5) * (waste_ratio - 0.5) * 40.0 + (waste_ratio - 0.5) * 10.0;
        }
        if n > 0 && pr < n { score += (n - pr) as f64 * 0.35; }
        if pr <= 3 && n > pr { score += 12.0; }
    }

    // Lookahead: next item snugly fits post residual.
    if n > 0 {
        if pr == n {
            score -= 14.0 + (item_size as f64 / cap) * 4.0;
        } else if pr > n {
            let after = pr - n;
            if after < 10 { score -= 10.0; }
            if after == 0 { score -= 18.0; }
            if after > 0 && after <= 12 { score -= 5.0; }
            if after >= n + n / 2 && after <= 2 * n { score -= 3.0; }
            if n >= 3 && n <= 12 && after % n == 0 { score -= 3.5; }
            if after % 10 == 0 { score -= 5.0; }
            if after % 25 == 0 { score -= 3.5; }
            if n >= 6 && after >= 2 * n { score -= 3.5 + (after / n.max(1)) as f64; }
            if after > 15 && after < 25 && after % 5 != 0 { score += 2.5; }
        } else {
            let shortfall = n - pr;
            score += 12.0 + shortfall as f64 * 0.06;
            if shortfall <= 4 { score -= 6.0; }
        }
        // Residual "primed" relative to next item.
        let gap = bin_residual as i64 - n as i64;
        if gap >= 0 && gap < 12 && bin_residual != bin_capacity {
            score -= 8.0 - gap as f64 * 0.5;
        } else if gap < 0 && (-gap) < n as i64 && bin_residual != bin_capacity {
            score += (-gap) as f64 * 0.30;
        }
    } else {
        score -= 8.0;
    }

    // Tightness scaled by fill ratio.
    let fill_ratio = 1.0 - bin_residual as f64 / cap;
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += tightness * (7.0 + 7.0 * fill_ratio);

    // Convex tilt toward below-average residuals.
    if bin_residual != bin_capacity {
        let dev = mean_residual - pr as f64;
        score -= dev * 0.20;
        if dev > 0.0 { score -= dev * 0.05; }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity && bin_residual >= item_size {
        score -= 30.0;
        let leftover = bin_residual - item_size;
        if leftover <= 5 { score -= 10.0; }
        if n > 0 && leftover >= n { score -= 6.0; }
        if n > 0 && leftover > n && leftover - n < 8 && leftover > 30 { score += 9.0; }
        if leftover == 0 { score -= 6.0; }
    }
    if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 7.5;
    }

    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fragmentation = mean_residual / cap;

    if bin_residual != bin_capacity {
        score -= pressure;
        let res_ratio = bin_residual as f64 / cap;
        if res_ratio < 0.25 {
            score -= (0.25 - res_ratio) * 14.0;
        }
        if progress < 0.3 && fragmentation < 0.15 {
            score -= res_ratio * 3.0;
        }
    } else {
        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 { score -= 15.0; }
        if n as f64 > cap * 0.6 { score -= 6.0; }
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if n > 0 && bin_capacity - item_size == n { score -= 12.0; }
        if fragmentation < 0.12 && progress > 0.1 { score += 4.0; }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if n > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= n {
                let after = fresh_post - n;
                if after == 0 { score -= 18.0; }
                else if after <= n / 2 { score -= 8.0; }
                else if after <= 12 { score -= 4.0; }
            }
        }
        if pr > 0 && pr <= 8 { score -= 5.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;

    // Base: waste after placement, normalized
    let mut score = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, tolerate moderate residual; late, punish it quadratically.
    let p2 = post / cap * post / cap;
    score += p2 * (0.5 + 1.5 * progress);

    // Smooth interaction: reward tight fits more as stream progresses.
    let tightness = 1.0 - (item / res.max(1.0));
    score -= (1.0 - tightness).powi(3) * (0.3 + 0.7 * progress);

    // Penalize residual that cannot plausibly fit the next item (smooth logistic coupling).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit_prob = 1.0 / (1.0 + (-(post - n) / 10.0).exp());
        score += (1.0 - fit_prob) * 0.4 * (0.5 + progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 0.8 + 0.4 * progress;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor,
    // but less penalized early (many items still to come).
    if bin_residual == bin_capacity {
        score += 0.55 - 0.35 * progress;
    }

    // Mild coupling with mean residual: prefer bins below mean (balance residuals).
    score += 0.15 * ((res - mean_residual) / cap);

    // Slight preference to fill bins with many open bins (consolidation pressure).
    score += 0.05 * (post / cap) * (open_bins_count as f64).ln().max(0.0);

    score
}

