    // to stream progress, push harder toward finishing nearly-full bins so
    // total bin count tracks the theoretical minimum more tightly.
    if bin_residual != bin_capacity && open_bins_count as f64 > (total_items.max(1) as f64).ln() * 4.0 {
        score -= (bin_residual as f64 / cap) * 2.5;
    }

    score
}

