    // given typical item sizes, so penalize them heavily.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    // Mid-range gaps (10..=20) are moderately risky; larger gaps stay reusable.
    if post_residual > 9 && post_residual <= 20 {
        score += 8.0;
