    // Prefer bins tighter than the mean residual (better fits).
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Early in the stream, be slightly more willing to open bins for good fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if is_new_bin {
        score -= (1.0 - progress) * 5.0;
    }

    score
}

