            score -= res_ratio * 3.0;
        }
        // Convex tilt toward bins below mean residual — close fullest bins first.
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= dev * 0.10;
        }
        // NEW: near-exact-fill bonus — if item nearly closes this bin, reward
        // proportionally to how close the post residual is to a "useful"
        // remainder (zero or exactly next item size).
        if pr > 0 && n > 0 {
            if pr <= 2 {
                score -= 9.0;
            } else if (pr as i64 - n as i64).abs() <= 2 {
                score -= 8.0;
            }
        }
    } else {
        // New-bin candidate: penalize, more so late in the stream.
        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if n as f64 > cap * 0.6 {
            score -= 6.0;
        }
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if n > 0 && bin_capacity - item_size == n {
            score -= 12.0;
        }
        if fragmentation < 0.12 && progress > 0.1 {
            score += 4.0;
        }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if n > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= n {
                let after = fresh_post - n;
                if after == 0 {
                    score -= 18.0;
                } else if after <= n / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
                // Triple-completion potential in a fresh bin.
                if after >= n && after - n < 8 {
                    score -= 5.0;
                }
            } else if n <= bin_capacity {
                score += 4.0;
            }
        }
        if pr > 0 && pr <= 8 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity.max(1) as f64;
    let n = next_item_size;

    // Harmonic residue classes: reward reusable remainders, punish awkward gaps.
    if pr < 12 {
        score -= 28.0 + (12 - pr) as f64 * 3.0;
        if pr == 0 {
            score -= 14.0;
        }
        if n > 0 && pr >= 1 && pr <= 3 && n > pr {
            score += 5.0;
        }
        if n > 0 && pr >= 1 && pr <= 3 && n == pr {
            score -= 10.0;
        }
        if n > 0 && pr >= n && pr - n <= 1 {
            score -= 9.0;
        }
    } else if pr < 28 {
        let d = (28 - pr) as f64;
        score += 11.0 + d * (1.0 + 0.03 * d);
        if n >= 12 && n <= pr {
            score -= 18.0;
        }
        if n >= 8 && pr >= 2 * n {
            score -= 9.0;
        }
        if n > 0 && pr >= n && (pr - n) < 4 {
            score -= 4.0;
        }
    } else {
        if pr % 5 == 0 { score -= 5.5; }
        if pr % 10 == 0 { score -= 4.5; }
        if pr % 25 == 0 { score -= 3.5; }
        if n > 0 && pr > n && pr - n <= 10 {
            score -= 4.5;
        }
        if n >= 10 {
            let r = pr % n;
            if r > 0 && n - r <= 4 {
                score -= 3.0;
            }
        }
        if n >= 15 && pr >= n + n / 2 {
            score -= 2.5;
        }
        if n > pr && pr > 28 && pr < 45 {
            score += 3.5;
        }
        if n >= 3 && n <= 12 && pr % n == 0 && pr > 0 {
            score -= 4.0;
        }
    }

    // Dead-space avoidance: residuals too small for the next item are waste.
    let min_useful = if n > 0 { n.min(80) } else { 10 };
    if pr > 0 && pr < min_useful {
        score += (min_useful - pr) as f64 * 6.0;
        if pr <= 5 {
            score += 25.0;
        }
        if pr < min_useful / 2 {
            score += (min_useful / 2 - pr) as f64 * 4.0;
        }
        if n > 4 && pr > 3 {
            score += (n - pr) as f64 * 0.55;
        }
        if pr <= 3 && n > pr {
            score += 12.0;
        }
    }

    // Perfect closure is the strongest compaction signal.
    if pr == 0 {
        score -= 30.0;
    }

    // Quadratic waste penalty for large leftovers.
    if pr > 0 {
        let waste_ratio = pr as f64 / cap;
        if waste_ratio > 0.5 {
            score += (waste_ratio - 0.5) * (waste_ratio - 0.5) * 40.0 + (waste_ratio - 0.5) * 10.0;
        }
        if n > 0 && pr < n {
            score += (n - pr) as f64 * 0.35;
        }
    }

    // Tight fit reward: quadratic near-full bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.80 {
        score -= (fit_ratio - 0.80) * (fit_ratio - 0.80) * 90.0;
    }
    if fit_ratio > 0.97 {
        score -= 14.0;
        if pr == 0 {
            score -= 6.0;
        }
    }

    // Two-step lookahead: chain fits strongly rewarded.
    if n > 0 {
        if n == pr {
            score -= 52.0 + (item_size as f64 / cap) * 4.0;
        } else if n < pr {
            let npr = pr - n;
            if npr < 12 { score -= 15.0; }
            if npr % 10 == 0 { score -= 5.0; }
            if npr % 25 == 0 { score -= 3.5; }
            if npr >= n && npr < 40 { score -= 2.5; }
            if npr >= 20 { score -= 4.0; }
            if n >= 6 && npr >= 2 * n {
                score -= 3.5 + (npr / n.max(1)) as f64;
            }
            if npr > 15 && npr < 25 && npr % 5 != 0 {
                score += 2.5;
            }
            if npr > 0 && npr <= 12 {
                score -= 5.0;
            }
            if npr >= n + n / 2 && npr <= 2 * n {
                score -= 3.0;
            }
            if n >= 3 && n <= 12 && npr % n == 0 {
                score -= 3.5;
            }
            // Double-chain lookahead: reward bins that can absorb two more items.
            if npr >= n {
                let npr2 = npr - n;
                if npr2 == 0 {
                    score -= 7.0;
                } else if npr2 < 6 {
                    score -= 4.0;
                } else if npr2 >= n && npr2 < 25 {
                    score -= 2.0;
                }
            }
            // NEW: exact divisibility chain — residual fully decomposable into
            // next-item multiples means zero future dead space.
            if n >= 2 && npr % n == 0 && npr / n >= 2 {
                score -= (npr / n) as f64 * 1.5;
            }
        } else {
            let shortfall = n - pr;
            score += 12.0 + shortfall as f64 * 0.06;
            if shortfall <= 4 { score -= 6.0; }
        }
        // Residual "primed" relative to next item.
        let gap = bin_residual as i64 - n as i64;
        if gap >= 0 && gap < 12 && bin_residual != bin_capacity {
            score -= 8.0 - gap as f64 * 0.5;
        } else if gap < 0 && (-gap) < n as i64 && bin_residual != bin_capacity {
            score += (-gap) as f64 * 0.30;
        }
    } else {
        score -= 8.0;
    }

    // Tightness scaled by fill ratio.
    let fill_ratio = 1.0 - bin_residual as f64 / cap;
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += tightness * (7.0 + 7.0 * fill_ratio);

    // Deviation from mean residual: nearly-full bins preferred.
    score += (pr as f64 - mean_residual) * 0.40;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity && bin_residual >= item_size {
        score -= 34.0;
        if bin_residual - item_size <= 5 { score -= 10.0; }
        if n > 0 && bin_residual - item_size >= n {
            score -= 6.0;
        }
        let leftover = bin_residual - item_size;
        if n > 0 && leftover > n && leftover - n < 8 && leftover > 30 {
            score += 9.0;
        }
        if leftover == 0 { score -= 6.0; }
    }
    if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 7.5;
    }

    // Open-bin pressure (logarithmic to tolerate many open bins).
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fragmentation = mean_residual / cap;

    if bin_residual != bin_capacity {
        score -= pressure;
        let res_ratio = bin_residual as f64 / cap;
        if res_ratio < 0.25 {
            score -= (0.25 - res_ratio) * 14.0;
        }
        if progress < 0.3 && fragmentation < 0.15 {
            score -= res_ratio * 3.0;
        }
        // Convex tilt toward bins below mean residual.
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= dev * 0.10;
        }
        // NEW: near-closure sprint — bins within one small item of fullness
        // get an extra push to convert residual into zero dead space.
        if n > 0 && bin_residual - item_size <= n && bin_residual - item_size > 0 {
            score -= 4.0;
        }
    } else {
        // New-bin candidate: penalize, more so late in the stream.
        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if n as f64 > cap * 0.6 {
            score -= 6.0;
        }
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if n > 0 && bin_capacity - item_size == n {
            score -= 12.0;
        }
        if fragmentation < 0.12 && progress > 0.1 {
            score += 4.0;
        }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if n > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= n {
                let after = fresh_post - n;
                if after == 0 {
                    score -= 18.0;
                } else if after <= n / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
                if after >= n && after - n < 8 {
                    score -= 5.0;
                }
                // NEW: exact multiple packing in a fresh bin.
                if n >= 2 && after > 0 && after % n == 0 {
                    score -= (after / n) as f64 * 2.0;
                }
            } else if n <= bin_capacity {
                score += 4.0;
            }
        }
        if pr > 0 && pr <= 8 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strong reward for leaving nothing behind.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Small residuals are increasingly valuable; superlinear penalty shaping.
        let pr = post_residual as f64;
        score += (pr / bin_capacity as f64).powi(2) * 20.0;
    }

    if next_item_size > 0 {
        // Aggressive 2-step lookahead: if the next item fits exactly into post_residual,
        // this bin is a perfect 2-item chain — reward heavily.
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            if gap == 0.0 {
                score -= 800.0;
            } else {
                // Reward proportional to how snugly the next item fits.
                score -= 60.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item cannot follow: penalize if post_residual is a "dead zone"
            // just barely too small for the next item (wasted space).
            let overshoot = (next_item_size - post_residual) as f64;
            if overshoot <= 10.0 {
                score += 40.0 * (1.0 - overshoot / 10.0);
            }
        }
    }

    // Relative-to-mean coupling: bins with residuals below the mean are already
    // tight; placing here fragments them. Bins above the mean are roomy.
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= rel * 15.0;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 25.0;
    }

    // Late in the stream, prefer closing out bins (consolidation pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize opening a new bin when good existing fits exist: new-bin candidate
    // (residual == capacity) gets a baseline handicap unless item is huge.
    if bin_residual == bin_capacity {
        score += 30.0 + item_size as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;

    // Dead-space avoidance scaled to what's actually usable next.
    let min_useful = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        score += (min_useful - post_residual) as f64 * 6.0;
        if post_residual <= 5 {
            score += 25.0;
        }
        if post_residual < min_useful / 2 {
            score += (min_useful / 2 - post_residual) as f64 * 4.0;
        }
    }

    // Tight fit reward: quadratic near-full bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.80 {
        score -= (fit_ratio - 0.80) * (fit_ratio - 0.80) * 90.0;
    }
    if fit_ratio > 0.97 {
        score -= 14.0;
        if post_residual == 0 {
            score -= 6.0;
        }
    }
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: prefer using the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
        let leftover = bin_residual - item_size;
        if leftover <= 5 { score -= 8.0; }
        if next_item_size > 0 && leftover > next_item_size && leftover - next_item_size < 8 {
            score += 7.0;
        }
    }
    if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fragmentation = mean_residual / cap;

    // Residual "primed" relative to next item.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let gap = bin_residual as i64 - next_item_size as i64;
        if gap >= 0 && gap < 12 {
            score -= 8.0 - gap as f64 * 0.5;
        } else if gap < 0 && (-gap) < next_item_size as i64 {
            score += (-gap) as f64 * 0.30;
        }
    }

    if bin_residual != bin_capacity {
        score -= pressure;
        if progress < 0.3 && fragmentation < 0.15 {
            score -= (bin_residual as f64 / cap) * 3.0;
        }
        // Deep-fill bias: bins closest to closure get a sharper tilt,
        // now with a smooth (rather than hard-thresholded) component so
        // mid-size residuals also feel a gentle pull toward consolidation.
        let res_ratio = bin_residual as f64 / cap;
        score -= (1.0 - res_ratio) * (1.0 - res_ratio) * 4.0;
        if res_ratio < 0.25 {
            score -= (0.25 - res_ratio) * 18.0;
        } else if res_ratio < 0.45 {
            score -= (0.45 - res_ratio) * 5.0;
        }
    } else {
        // New-bin candidate: penalize, more so late in the stream.
        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if next_item_size as f64 > cap * 0.6 {
            score -= 6.0;
        }
        if mean_residual > cap * 0.35 {
            score -= 4.0;
        }
        if post_residual > 0 && post_residual <= 8 {
            score -= 5.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 12.0;
        }
        if fragmentation < 0.12 && progress > 0.1 {
            score += 4.0;
        }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if next_item_size > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= next_item_size {
                let after = fresh_post - next_item_size;
                if after == 0 {
                    score -= 18.0;
                } else if after <= next_item_size / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
            }
        }
        // Fragmented open bins make a fresh bin attractive.
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
    }

    // Prefer bins whose residual is below average, with convex tilt.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= dev * 0.20;
        if dev > 0.0 {
            score -= dev * 0.05;
        }
    }

    // Lookahead: reward when next item fits snugly in post residual.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 10.0;
    }
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 14.0 + (item_size as f64 / cap) * 4.0;
    }

    // Three-item chain potential.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next > 0 && after_next <= 12 {
            score -= 5.0;
        }
        if after_next >= next_item_size + next_item_size / 2 && after_next <= 2 * next_item_size {
            score -= 3.0;
        }
        if next_item_size >= 3 && next_item_size <= 12 && after_next % next_item_size == 0 {
            score -= 3.5;
        }
    }

    // Quadratic waste penalty for large leftovers.
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap;
        if waste_ratio > 0.5 {
            score += (waste_ratio - 0.5) * (waste_ratio - 0.5) * 40.0 + (waste_ratio - 0.5) * 10.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
        // Escalating terminal-waste penalty — dead space below smallest items.
        if post_residual <= 3 && next_item_size > post_residual {
            score += 12.0;
        }
        // Mid-band dead zone: residuals just below the next item size are the
        // primary source of wasted bins; widen the band and scale with both
        // the shortfall and how much of the capacity the dead band represents.
        if next_item_size > 4 && post_residual < next_item_size && post_residual > 3 {
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.70 + shortfall * shortfall / cap * 0.5;
        }
        // NEW: exact-multiple chain bonus — if post residual is an exact
        // multiple of the next item size, a full chain of placements is
        // possible; reward it proportionally to the number of fits.
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            let fits = post_residual / next_item_size;
            if fits >= 2 {
                score -= (fits.min(5) as f64) * 4.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = if bin_residual > 0 {
        item_size as f64 / bin_residual as f64
    } else {
        1.0
    };
    if fit_ratio <= 1.0 {
        // Perfect or near-perfect fit gets a large discount.
        score -= 25.0 * fit_ratio * fit_ratio;
    } else {
        // Should not happen for a fitting bin, but guard.
        score += 1000.0;
    }

    // Reward near-exact fits (post_residual very small) with a nonlinear bonus.
    if post_residual <= 5 {
        score -= 20.0 * (6 - post_residual) as f64;
    } else if post_residual <= 15 {
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // to avoid wasting it and forcing a new bin later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // Lookahead coupling: if the next item could exactly consume the post_residual,
    // this placement is especially valuable.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item still fits after this placement: mildly good.
            score -= 4.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // Next item won't fit in the leftover: penalize large unusable leftovers.
            score += 3.0 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Global state: penalize bins whose residual deviates above the mean residual
    // (keeping residuals homogeneous preserves flexibility).
    let deviation = post_residual as f64 - mean_residual;
    if deviation > 0.0 {
        score += 0.3 * deviation;
    } else {
        score += 0.1 * deviation; // small reward for below-mean residual
    }

    // Time horizon: late in the stream, consolidate aggressively into fewer bins.
    if progress > 0.7 {
        score -= 5.0 * (progress - 0.7) * (open_bins_count as f64).max(1.0).log2();
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Give it a base penalty that shrinks when the item is
    // large relative to capacity (few open bins could ever take it later anyway).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a new bin.
        let mut new_bin_penalty = 35.0;
        // If many bins fit the item, opening a new one is rarely justified.
        if fitting_bins_count > 1 {
            new_bin_penalty += 10.0 * (fitting_bins_count as f64);
        }
        // If no open bin fits, this call is the fallback; reduce penalty when
        // the item is big (hard to place later).
        if fitting_bins_count == 0 {
            new_bin_penalty -= 20.0 + 15.0 * item_frac;
        }
        // Late in the stream, prefer closing out open bins over spawning new ones.
        new_bin_penalty += 10.0 * progress;
