            score -= (0.25 - res_ratio) * 14.0;
        }
        if progress < 0.3 && fragmentation < 0.15 {
            score -= res_ratio * 3.0;
        }
        // NEW: escalate deep-fill bias as stream progresses — closing bins
        // late matters more since leftover fragments can never be reclaimed.
        if progress > 0.5 && res_ratio < 0.5 {
            score -= (0.5 - res_ratio) * (progress - 0.5) * 20.0;
        }
    } else {
        // New-bin candidate: penalize, more so late in the stream.
        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if n as f64 > cap * 0.6 {
            score -= 6.0;
        }
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if n > 0 && bin_capacity - item_size == n {
            score -= 12.0;
        }
        if fragmentation < 0.12 && progress > 0.1 {
            score += 4.0;
        }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if n > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= n {
                let after = fresh_post - n;
                if after == 0 {
                    score -= 18.0;
                } else if after <= n / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
                // Triple-completion potential in a fresh bin.
                if after >= n && after - n < 8 {
                    score -= 5.0;
                }
                // NEW: fresh-bin divisibility — a capacity that packs the
                // current item into an exact partition is a perfect bin.
                if item_size > 0 && bin_capacity % item_size == 0 {
                    score -= 6.0;
                }
            } else if n <= bin_capacity {
                score += 4.0;
            }
        }
        if pr > 0 && pr <= 8 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fill classes are golden.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: residual divisible into common item sizes (10/20/25/50)
    // is reusable; odd fragments are dead space.
    let reusable = (post_residual % 10 == 0) as f64 * 15.0
        + (post_residual % 20 == 0) as f64 * 10.0
        + (post_residual % 25 == 0) as f64 * 8.0
        + (post_residual % 50 == 0) as f64 * 6.0;
    score -= reusable;

    // Small dead fragments (< 10) are unusable: penalize proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 - 2.0 * post as f64;
    }

    // Lookahead coupling: reward if next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.3 * (next_item_size as f64);
        } else {
            // Post residual too small for next item: dead space risk.
            score += 0.4 * (next_item_size as f64 - post);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: prefer reusing open bins early, allow opening
    // new bins late in the stream or when open bins are nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 - 25.0 * progress;
        score += 0.5 * (open_bins_count as f64);
        // If mean residual across open bins is small, a fresh bin is fine.
        score -= (mean_residual / cap).min(1.0) * 10.0;
    }

    // Mild preference for tighter bins among equals.
    score -= 0.1 * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity.max(1) as f64;
    let n = next_item_size;

    // Dead-space avoidance scaled to what's actually usable next.
    let min_useful = if n > 0 { n.min(80) } else { 10 };
    if pr > 0 && pr < min_useful {
        score += (min_useful - pr) as f64 * 6.5;
        if pr <= 5 { score += 25.0; }
        if pr < min_useful / 2 { score += (min_useful / 2 - pr) as f64 * 4.0; }
        if n > 4 && pr > 3 { score += (n - pr) as f64 * 0.55; }
        if pr <= 3 && n > pr { score += 12.0; }
    }

    // Perfect closure.
    if pr == 0 { score -= 34.0; }

    // Tight fit reward: quadratic near-full bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.76 {
        score -= (fit_ratio - 0.76) * (fit_ratio - 0.76) * 100.0;
    }
    if fit_ratio > 0.97 {
        score -= 16.0;
        if pr == 0 { score -= 6.0; }
    }

    // Quadratic waste penalty for large leftovers.
    if pr > 0 {
        let waste_ratio = pr as f64 / cap;
        if waste_ratio > 0.5 {
            score += (waste_ratio - 0.5) * (waste_ratio - 0.5) * 40.0 + (waste_ratio - 0.5) * 10.0;
        }
        if n > 0 && pr < n { score += (n - pr) as f64 * 0.35; }
        // Mid-band dead zone: residual just below next item is prime waste.
        if n > 4 && pr < n && pr > 3 { score += (n - pr) as f64 * 0.20; }
    }

    // Lookahead: next item snugly fits post residual.
    if n > 0 {
        if pr == n {
            score -= 16.0 + (item_size as f64 / cap) * 4.0;
        } else if pr > n {
            let after = pr - n;
            if after < 10 { score -= 10.0; }
            if after == 0 { score -= 18.0; }
            if after > 0 && after <= 12 { score -= 5.0; }
            if after >= n + n / 2 && after <= 2 * n { score -= 3.0; }
            if n >= 3 && n <= 12 && after % n == 0 { score -= 3.5; }
            if after % 10 == 0 { score -= 5.0; }
            if after % 25 == 0 { score -= 3.5; }
            if n >= 6 && after >= 2 * n { score -= 3.5 + (after / n.max(1)) as f64; }
            if after > 15 && after < 25 && after % 5 != 0 { score += 2.5; }
        } else {
            let shortfall = n - pr;
            score += 12.0 + shortfall as f64 * 0.06;
            if shortfall <= 4 { score -= 6.0; }
        }
        // Residual "primed" relative to next item.
        let gap = bin_residual as i64 - n as i64;
        if gap >= 0 && gap < 12 && bin_residual != bin_capacity {
            score -= 8.0 - gap as f64 * 0.5;
        } else if gap < 0 && (-gap) < n as i64 && bin_residual != bin_capacity {
            score += (-gap) as f64 * 0.30;
        }
    } else {
        score -= 8.0;
    }

    // Tightness scaled by fill ratio.
    let fill_ratio = 1.0 - bin_residual as f64 / cap;
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += tightness * (7.0 + 7.0 * fill_ratio);

    // Convex tilt toward below-average residuals.
    if bin_residual != bin_capacity {
        let dev = mean_residual - pr as f64;
        score -= dev * 0.20;
        if dev > 0.0 { score -= dev * 0.05; }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity && bin_residual >= item_size {
        score -= 30.0;
        let leftover = bin_residual - item_size;
        if leftover <= 5 { score -= 10.0; }
        if n > 0 && leftover >= n { score -= 6.0; }
        if n > 0 && leftover > n && leftover - n < 8 && leftover > 30 { score += 9.0; }
        if leftover == 0 { score -= 6.0; }
    }
    if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 7.5;
    }

    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fragmentation = mean_residual / cap;

    if bin_residual != bin_capacity {
        score -= pressure;
        let res_ratio = bin_residual as f64 / cap;
        if res_ratio < 0.25 {
            score -= (0.25 - res_ratio) * 16.0;
        }
        if progress < 0.3 && fragmentation < 0.15 {
            score -= res_ratio * 3.0;
        }
    } else {
        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 { score -= 15.0; }
        if n as f64 > cap * 0.6 { score -= 6.0; }
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if n > 0 && bin_capacity - item_size == n { score -= 12.0; }
        if fragmentation < 0.12 && progress > 0.1 { score += 4.0; }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if n > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= n {
                let after = fresh_post - n;
                if after == 0 { score -= 18.0; }
                else if after <= n / 2 { score -= 8.0; }
                else if after <= 12 { score -= 4.0; }
            }
        }
        if pr > 0 && pr <= 8 { score -= 5.0; }
        // Fresh-bin residual matching clean multiples of 10 is attractive.
        let fresh_post = bin_capacity.saturating_sub(item_size);
        if fresh_post >= 10 && fresh_post <= 50 && fresh_post % 10 == 0 { score -= 2.0; }
        // NEW: if the current item alone nearly closes a fresh bin, and no
        // open bin closes with it, opening is cheaper than fragmenting.
        if item_size as f64 >= cap * 0.9 && fitting_bins_count <= 2 { score -= 10.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space disproportionately.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins that can also fit the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: encourage consolidation when many bins open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Slight preference for bins with larger residuals among comparable fits.
    score += (mean_residual - post_residual as f64) * 0.1;

    // New-bin candidate: neutral-ish baseline; only chosen when open bins score poorly.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
