pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits into post_residual exactly.
    if next_item_size > 0 {
        let pr = post_residual as u32;
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            // Perfect match: next item fills bin completely.
            if gap == 0 {
                score -= 60.0;
            } else {
                // Reward tight follow-up fits proportionally to tightness.
                score -= 40.0 * (1.0 - gap as f64 / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here: penalize leaving a small unusable sliver.
            if pr < 10 {
                score += 25.0;
            }
        }
    } else {
        // Last item: prefer filling existing bins as tightly as possible.
        score -= 15.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below the mean (denser bins).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // no open bin offers a decent fit (post_residual would be tiny sliver risk).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit_among_open = fitting_bins_count == 0;
        // Penalize new bins generally, more so later in the stream.
        score += 20.0 + 40.0 * progress;
        if poor_fit_among_open {
            score -= 35.0;
        }
        // If next item is large, a fresh bin gives it room later; mild bonus.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mild penalty for wasting large residual capacity on small items.
    if (bin_residual as f64) > 1.5 * item_size as f64 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
