            score += 25.0;
        }
        if post_residual < min_useful / 2 {
            score += (min_useful / 2 - post_residual) as f64 * 4.0;
        }
    }

    // Tight fit reward: quadratic near-full bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.80 {
        score -= (fit_ratio - 0.80) * (fit_ratio - 0.80) * 90.0;
    }
    if fit_ratio > 0.97 {
        score -= 14.0;
        if post_residual == 0 {
            score -= 6.0;
        }
    }
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: prefer using the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
        let leftover = bin_residual - item_size;
        if leftover <= 5 { score -= 8.0; }
        if next_item_size > 0 && leftover > next_item_size && leftover - next_item_size < 8 {
            score += 7.0;
        }
    }
    if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fragmentation = mean_residual / cap;

    // Residual "primed" relative to next item.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let gap = bin_residual as i64 - next_item_size as i64;
        if gap >= 0 && gap < 12 {
            score -= 8.0 - gap as f64 * 0.5;
        } else if gap < 0 && (-gap) < next_item_size as i64 {
            score += (-gap) as f64 * 0.30;
        }
    }

    if bin_residual != bin_capacity {
        score -= pressure;
        if progress < 0.3 && fragmentation < 0.15 {
            score -= (bin_residual as f64 / cap) * 3.0;
        }
        // Deep-fill bias — bins closest to closure get tilted harder,
        // with an extra nudge when the remaining space is truly tiny.
        let res_ratio = bin_residual as f64 / cap;
        if res_ratio < 0.25 {
            score -= (0.25 - res_ratio) * 14.0;
        }
        if res_ratio < 0.08 {
            score -= (0.08 - res_ratio) * 30.0;
        }
    } else {
        // New-bin candidate: penalize, more so late in the stream.
        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if next_item_size as f64 > cap * 0.6 {
            score -= 6.0;
        }
        if mean_residual > cap * 0.35 {
            score -= 4.0;
        }
        if post_residual > 0 && post_residual <= 8 {
            score -= 5.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 12.0;
        }
        if fragmentation < 0.12 && progress > 0.1 {
            score += 4.0;
        }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if next_item_size > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= next_item_size {
                let after = fresh_post - next_item_size;
                if after == 0 {
                    score -= 18.0;
                } else if after <= next_item_size / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
            }
        }
        // Fragmented open bins make a fresh bin attractive.
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
    }

    // Prefer bins whose residual is below average, with convex tilt.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= dev * 0.20;
        if dev > 0.0 {
            score -= dev * 0.05;
        }
    }

    // Lookahead: reward when next item fits snugly in post residual.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 10.0;
    }
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 14.0 + (item_size as f64 / cap) * 4.0;
    }

    // Three-item chain potential.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next > 0 && after_next <= 12 {
            score -= 5.0;
        }
        if after_next >= next_item_size + next_item_size / 2 && after_next <= 2 * next_item_size {
            score -= 3.0;
        }
        if next_item_size >= 3 && next_item_size <= 12 && after_next % next_item_size == 0 {
            score -= 3.5;
        }
    }

    // Quadratic waste penalty for large leftovers.
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap;
        if waste_ratio > 0.5 {
            score += (waste_ratio - 0.5) * (waste_ratio - 0.5) * 40.0 + (waste_ratio - 0.5) * 10.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
        // Escalating terminal-waste penalty — dead space below smallest items.
        if post_residual <= 3 && next_item_size > post_residual {
            score += 12.0;
        }
        // Mid-band dead zone — residuals that neither fit the next item
        // nor are near-zero are the main source of wasted bins.
        if next_item_size > 4 && post_residual < next_item_size && post_residual > 3 {
            score += (next_item_size - post_residual) as f64 * 0.55;
        }
        // NEW: post-residual vs. global mean — a leftover far above the
        // average residual is likely to strand; nudge toward bins whose
        // post-residual lands near the usable mean instead.
        if post_residual as f64 > mean_residual * 1.6 && post_residual > 15 {
            score += (post_residual as f64 - mean_residual * 1.6) * 0.40;
        }
    }

    // NEW: closing-window bias — when few items remain, prioritize exact
    // closure over lookahead rewards since the future matters less.
    let items_left = total_items.saturating_sub(step_index);
    if items_left <= 3 && bin_residual != bin_capacity {
        if post_residual == 0 {
            score -= 20.0;
        } else {
            score += (post_residual as f64) * 0.30;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity.max(1) as f64;
    let n = next_item_size;

    // Harmonic residue classes: reward reusable remainders, punish awkward gaps.
    if pr < 12 {
        score -= 28.0 + (12 - pr) as f64 * 3.0;
        if pr == 0 {
            score -= 14.0;
        }
        if n > 0 && pr >= 1 && pr <= 3 && n > pr {
            score += 5.0;
        }
        if n > 0 && pr >= 1 && pr <= 3 && n == pr {
            score -= 10.0;
        }
        if n > 0 && pr >= n && pr - n <= 1 {
            score -= 9.0;
        }
    } else if pr < 28 {
        let d = (28 - pr) as f64;
        score += 11.0 + d * (1.0 + 0.03 * d);
        if n >= 12 && n <= pr {
            score -= 18.0;
        }
        if n >= 8 && pr >= 2 * n {
            score -= 9.0;
        }
        if n > 0 && pr >= n && (pr - n) < 4 {
            score -= 4.0;
        }
    } else {
        if pr % 5 == 0 { score -= 5.5; }
        if pr % 10 == 0 { score -= 4.5; }
        if pr % 25 == 0 { score -= 3.5; }
        if n > 0 && pr > n && pr - n <= 10 {
            score -= 4.5;
        }
        if n >= 10 {
            let r = pr % n;
            if r > 0 && n - r <= 4 {
                score -= 3.0;
            }
        }
        if n >= 15 && pr >= n + n / 2 {
            score -= 2.5;
        }
        if n > pr && pr > 28 && pr < 45 {
            score += 3.5;
        }
        if n >= 3 && n <= 12 && pr % n == 0 && pr > 0 {
            score -= 4.0;
        }
    }

    // Dead-space avoidance: residuals too small for the next item are waste.
    let min_useful = if n > 0 { n.min(80) } else { 10 };
    if pr > 0 && pr < min_useful {
        score += (min_useful - pr) as f64 * 6.0;
        if pr <= 5 {
            score += 25.0;
        }
        if pr < min_useful / 2 {
            score += (min_useful / 2 - pr) as f64 * 4.0;
        }
        if n > 4 && pr > 3 {
            score += (n - pr) as f64 * 0.55;
        }
        if pr <= 3 && n > pr {
            score += 12.0;
        }
    }

    // Perfect closure is the strongest compaction signal.
    if pr == 0 {
        score -= 30.0;
    }

    // Quadratic waste penalty for large leftovers.
    if pr > 0 {
        let waste_ratio = pr as f64 / cap;
        if waste_ratio > 0.5 {
            score += (waste_ratio - 0.5) * (waste_ratio - 0.5) * 40.0 + (waste_ratio - 0.5) * 10.0;
        }
        if n > 0 && pr < n {
            score += (n - pr) as f64 * 0.35;
        }
    }

    // Tight fit reward: quadratic near-full bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.80 {
        score -= (fit_ratio - 0.80) * (fit_ratio - 0.80) * 90.0;
    }
    if fit_ratio > 0.97 {
        score -= 14.0;
        if pr == 0 {
            score -= 6.0;
        }
    }

    // Two-step lookahead: chain fits strongly rewarded.
    if n > 0 {
        if n == pr {
            score -= 52.0 + (item_size as f64 / cap) * 4.0;
        } else if n < pr {
            let npr = pr - n;
            if npr < 12 { score -= 15.0; }
            if npr % 10 == 0 { score -= 5.0; }
            if npr % 25 == 0 { score -= 3.5; }
            if npr >= n && npr < 40 { score -= 2.5; }
            if npr >= 20 { score -= 4.0; }
            if n >= 6 && npr >= 2 * n {
                score -= 3.5 + (npr / n.max(1)) as f64;
            }
            if npr > 15 && npr < 25 && npr % 5 != 0 {
                score += 2.5;
            }
            if npr > 0 && npr <= 12 {
                score -= 5.0;
            }
            if npr >= n + n / 2 && npr <= 2 * n {
                score -= 3.0;
            }
            if n >= 3 && n <= 12 && npr % n == 0 {
                score -= 3.5;
            }
            // Double-chain lookahead: bin can absorb two more items.
            if npr >= n {
                let npr2 = npr - n;
                if npr2 == 0 {
                    score -= 7.0;
                } else if npr2 < 6 {
                    score -= 4.0;
                } else if npr2 >= n && npr2 < 25 {
                    score -= 2.0;
                }
            }
        } else {
            let shortfall = n - pr;
            score += 12.0 + shortfall as f64 * 0.06;
            if shortfall <= 4 { score -= 6.0; }
        }
        // Residual "primed" relative to next item.
        let gap = bin_residual as i64 - n as i64;
        if gap >= 0 && gap < 12 && bin_residual != bin_capacity {
            score -= 8.0 - gap as f64 * 0.5;
        } else if gap < 0 && (-gap) < n as i64 && bin_residual != bin_capacity {
            score += (-gap) as f64 * 0.30;
        }
    } else {
        score -= 8.0;
    }

    // Tightness scaled by fill ratio.
    let fill_ratio = 1.0 - bin_residual as f64 / cap;
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += tightness * (7.0 + 7.0 * fill_ratio);

    // Deviation from mean residual: nearly-full bins preferred (convex tilt).
    let dev = pr as f64 - mean_residual;
    score += dev * 0.40;
    if bin_residual != bin_capacity && dev < 0.0 {
        score += dev * 0.05;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity && bin_residual >= item_size {
        score -= 34.0;
        if bin_residual - item_size <= 5 { score -= 10.0; }
        if n > 0 && bin_residual - item_size >= n {
            score -= 6.0;
        }
        let leftover = bin_residual - item_size;
        if n > 0 && leftover > n && leftover - n < 8 && leftover > 30 {
            score += 9.0;
        }
        if leftover == 0 { score -= 6.0; }
    }
    if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 7.5;
    }

    // Open-bin pressure (logarithmic to tolerate many open bins).
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fragmentation = mean_residual / cap;

    if bin_residual != bin_capacity {
        score -= pressure;
        let res_ratio = bin_residual as f64 / cap;
        if res_ratio < 0.25 {
            score -= (0.25 - res_ratio) * 14.0;
        }
        if progress < 0.3 && fragmentation < 0.15 {
            score -= res_ratio * 3.0;
        }
        // Escalate deep-fill bias as stream progresses.
        if progress > 0.5 && res_ratio < 0.5 {
            score -= (0.5 - res_ratio) * (progress - 0.5) * 20.0;
        }
        // NEW: mid-band dead-zone tilt — bins whose residual sits just below
        // the next item size are prime waste sources; push them harder as
        // stream progresses since fragments can never be reclaimed.
        if n > 4 && bin_residual < n {
            score += (n - bin_residual) as f64 * (0.20 + progress * 0.30);
        }
    } else {
        // New-bin candidate: penalize, more so late in the stream.
        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if n as f64 > cap * 0.6 {
            score -= 6.0;
        }
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if n > 0 && bin_capacity - item_size == n {
            score -= 12.0;
        }
        if fragmentation < 0.12 && progress > 0.1 {
            score += 4.0;
        }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if n > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= n {
                let after = fresh_post - n;
                if after == 0 {
                    score -= 18.0;
                } else if after <= n / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
                if after >= n && after - n < 8 {
                    score -= 5.0;
                }
                // Fresh-bin divisibility: capacity packs current item exactly.
                if item_size > 0 && bin_capacity % item_size == 0 {
                    score -= 6.0;
                }
                // NEW: fresh-bin triple-chain divisibility — capacity evenly
                // split by next item promises a perfectly packed bin.
                if n >= 3 && bin_capacity % n == 0 && item_size as f64 <= cap * 0.5 {
                    score -= 4.0;
                }
            } else if n <= bin_capacity {
                score += 4.0;
            }
        }
        if pr > 0 && pr <= 8 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1), with a soft horizon.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let horizon = (1.0 - progress).max(0.05);

    // Perfect fit reward: strongly favor exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward small post residuals non-linearly (dead-space penalty).
        score += (post_residual as f64).powf(1.6) * 0.05;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 30.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving large unusable gaps.
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Global state coupling: many open bins with large mean residual -> prefer consolidation.
    let avg_resid = if open_bins_count > 0 { mean_residual } else { 0.0 };
    if bin_residual < avg_resid {
        // This bin is tighter than average: good, fill it.
        score -= (avg_resid - bin_residual as f64) * 0.5;
    } else {
        // Looser than average: mild penalty, scaled by number of open bins.
        score += (bin_residual as f64 - avg_resid) * 0.2 * (open_bins_count.min(20) as f64 / 10.0);
    }

    // New-bin candidate handling: empty bin starts with a big penalty so it is
    // only chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 400.0;
        // Early in the stream or when open bins are fragmented, opening is cheaper.
        score -= 300.0 * horizon * (1.0 - avg_resid / bin_capacity as f64);
        // If next item is small, a fresh bin has good future utility.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 80.0;
        }
        // If very few bins can fit the item, opening a new one is more acceptable.
        if fitting_bins_count <= 1 {
            score -= 150.0;
        }
    }

    // Tight-fit bonus: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.7 {
        score -= 60.0 * (fill_ratio - 0.7) / 0.3;
    }

    // Late-stream urgency: avoid leaving scattered residuals near the end.
    score += (1.0 - horizon) * (post_residual as f64) * 0.15;

    score
}

