        }
        if after_next >= next_item_size + next_item_size / 2 && after_next <= 2 * next_item_size {
            score -= 3.0;
        }
        if next_item_size >= 3 && next_item_size <= 12 && after_next % next_item_size == 0 {
            score -= 3.5;
        }
    }

    // Quadratic waste penalty for large leftovers.
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap;
        if waste_ratio > 0.5 {
            score += (waste_ratio - 0.5) * (waste_ratio - 0.5) * 40.0 + (waste_ratio - 0.5) * 10.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
        // Escalating terminal-waste penalty — dead space below smallest items.
        if post_residual <= 3 && next_item_size > post_residual {
            score += 12.0;
        }
        // Mid-band dead zone — residuals that neither fit the next item
        // nor are near-zero are the main source of wasted bins.
        if next_item_size > 4 && post_residual < next_item_size && post_residual > 3 {
            score += (next_item_size - post_residual) as f64 * 0.55;
        }
        // NEW: two-step dead-zone — residual too small even for the item after
        // next (approximated by next_item_size again) signals a bin that will
        // strand space; penalize mildly so tight post-residuals still win.
        if post_residual < 6 && next_item_size > post_residual + 3 {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: class = post_residual / (capacity/10)
    let class_width = bin_capacity / 10;
    let post_class = post_residual / class_width;
    let next_class = next_item_size / class_width;

    // Exact fit: massive reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Post residual that exactly accommodates the lookahead item: reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 400.0;
    }

    // Post residual large enough to fit next item: moderate reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + 0.5 * post_residual as f64;
    } else if next_item_size > 0 {
        // Dead space relative to lookahead: penalize
        score += 40.0 + (next_item_size - post_residual) as f64 * 1.5;
    }

    // Harmonic class matching: if post_residual's class equals next item's class, chain likely
    if next_item_size > 0 && post_class == next_class && post_residual >= next_item_size {
        score -= 80.0;
    }

    // Penalize small unusable residuals (class 0 or 1 => post_residual < 20)
    if post_class <= 1 && post_residual > 0 {
        score += 120.0 - 10.0 * post_residual as f64;
    }

    // Integer division thresholds: reward leaving residuals in "useful" mid classes (2..=5 => 20..59)
    if post_class >= 2 && post_class <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 500.0;
        } else {
            // discourage opening new bin when open bins exist
            score += 150.0 + 20.0 * open_bins_count as f64;
        }
    }

    // Tightness reward: prefer bins where item fills a large fraction of residual
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 100.0 * fill_frac;

    // Mild pressure to keep mean residual low across fleet
    score += 0.3 * mean_residual;

    // Early stream: be slightly conservative (favor new bins less), late stream: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
