    if fit_ratio > 0.97 {
        score -= 14.0;
        if pr == 0 {
            score -= 6.0;
        }
    }
    if pr == 0 {
        score -= 30.0;
    }

    // Two-step lookahead: chain fits strongly rewarded.
    if n > 0 {
        if n == pr {
            score -= 52.0;
        } else if n < pr {
            let npr = pr - n;
            if npr < 12 { score -= 15.0; }
            if npr % 10 == 0 { score -= 5.0; }
            if npr % 25 == 0 { score -= 3.5; }
            if npr >= n && npr < 40 { score -= 2.5; }
            if npr >= 20 { score -= 4.0; }
            if n >= 6 && npr >= 2 * n {
