    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fragmentation = mean_residual / cap;

    // Residual "primed" relative to next item.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let gap = bin_residual as i64 - next_item_size as i64;
        if gap >= 0 && gap < 12 {
            score -= 8.0 - gap as f64 * 0.5;
        } else if gap < 0 && (-gap) < next_item_size as i64 {
            score += (-gap) as f64 * 0.30;
        }
    }

    if bin_residual != bin_capacity {
        score -= pressure;
        if progress < 0.3 && fragmentation < 0.15 {
            score -= (bin_residual as f64 / cap) * 3.0;
        }
        // Deep-fill bias — bins whose residual is already small are the
        // ones closest to closure; tilt harder as residual shrinks.
        let res_ratio = bin_residual as f64 / cap;
        if res_ratio < 0.25 {
            score -= (0.25 - res_ratio) * 14.0;
        }
        // NEW: closure-distance term — reward bins that are within a small
        // number of "average steps" of closing, scaled by stream progress.
        let steps_to_close = (bin_residual as f64 / item_size.max(1) as f64).ceil();
        if steps_to_close <= 2.0 {
            score -= (3.0 - steps_to_close) * (4.0 + progress * 6.0);
        }
    } else {
        // New-bin candidate: penalize, more so late in the stream.
        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if next_item_size as f64 > cap * 0.6 {
            score -= 6.0;
        }
        if mean_residual > cap * 0.35 {
            score -= 4.0;
        }
        if post_residual > 0 && post_residual <= 8 {
            score -= 5.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 12.0;
        }
        if fragmentation < 0.12 && progress > 0.1 {
            score += 4.0;
        }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if next_item_size > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= next_item_size {
                let after = fresh_post - next_item_size;
                if after == 0 {
                    score -= 18.0;
                } else if after <= next_item_size / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
            } else {
                // NEW: fresh bin that strands the next item entirely is
                // risky unless open bins are badly fragmented.
                if fragmentation < 0.25 {
                    score += (next_item_size - fresh_post) as f64 * 0.25;
                }
            }
        }
        // Fragmented open bins make a fresh bin attractive.
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
    }

    // Prefer bins whose residual is below average, with convex tilt.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= dev * 0.20;
        if dev > 0.0 {
            score -= dev * 0.05;
        }
    }

    // Lookahead: reward when next item fits snugly in post residual.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 10.0;
    }
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 14.0 + (item_size as f64 / cap) * 4.0;
    }

    // Three-item chain potential.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next > 0 && after_next <= 12 {
            score -= 5.0;
        }
        if after_next >= next_item_size + next_item_size / 2 && after_next <= 2 * next_item_size {
            score -= 3.0;
        }
        if next_item_size >= 3 && next_item_size <= 12 && after_next % next_item_size == 0 {
            score -= 3.5;
        }
    }

    // Quadratic waste penalty for large leftovers.
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap;
        if waste_ratio > 0.5 {
            score += (waste_ratio - 0.5) * (waste_ratio - 0.5) * 40.0 + (waste_ratio - 0.5) * 10.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
        // Escalating terminal-waste penalty — dead space below smallest items.
        if post_residual <= 3 && next_item_size > post_residual {
            score += 12.0;
        }
        // Mid-band dead zone — residuals that neither fit the next item
        // nor are near-zero are the main source of wasted bins.
        if next_item_size > 4 && post_residual < next_item_size && post_residual > 3 {
            score += (next_item_size - post_residual) as f64 * 0.55;
        }
        // NEW: late-stream dead-space escalation — leftover slack late in the
        // stream is much less likely to ever be filled, penalize harder.
        if progress > 0.6 && next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * (0.20 + (progress - 0.6) * 0.75);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // follow-up item (<= 12) are almost unusable; penalize them hard.
    let dead_threshold: u32 = 12;
    if post_residual > 0 && post_residual <= dead_threshold {
        score += 40.0 * (1.0 - (post_residual as f64) / (dead_threshold as f64));
    }

    // Penalize mid-range awkward gaps less severely but still noticeably.
    if post_residual > dead_threshold && post_residual < 30 {
        score += 8.0 * (1.0 - ((post_residual - dead_threshold) as f64) / (30.0 - dead_threshold as f64));
    }

    // Reward tight fits strongly (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness;

    // Perfect fit: essentially zero waste, big reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // (discourage opening new bins); with few bins, opening is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // New-bin candidate: make the empty bin moderately attractive only when
    // no open bin offers a decent fit; otherwise it should lose.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base handicap so existing bins with reasonable fits win.
        score += 15.0;
        // If this bin is the last chance, strongly favor using it over a new bin.
        if fitting_bins_count == 1 {
            score += 60.0;
        }
        // If the mean residual across open bins is large, opening a new bin
        // is wasteful; penalize more.
        score += 0.3 * mean_residual.max(0.0);
        // If the next item is large and this bin is empty, a fresh bin is fine.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    } else {
        // Last-chance bin among fitting bins: strong reward to use it now.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
        // Lookahead coupling: if the next item fits exactly in the post-residual,
        // reward preserving that possibility (chain fits).
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= dead_threshold {
            score -= 20.0;
        }
        // If next item cannot fit in post-residual and post-residual is small,
        // the leftover is truly dead space; extra penalty.
        if next_item_size > post_residual && post_residual > 0 && post_residual < 20 {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
