            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item does not fit: penalize proportionally to wasted gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 + gap * 0.5;
        }
    } else {
        // Last item: pure best-fit behavior is fine.
        score -= 5.0;
    }

    // Compare post_residual against mean residual across open bins.
    let mean_post = mean_residual - item_size as f64;
    if (post_residual as f64) < mean_post {
        score -= 8.0; // leaves less room than average -> tighter packing
    } else {
        score += (post_residual as f64 - mean_post).min(30.0) * 0.3;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin when it is not needed,
    // unless current bins are badly fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        score += 15.0;
        if mean_residual < 30.0 && open_bins_count > 0 {
            score -= 20.0; // existing bins are nearly full; a fresh bin is reasonable
