    } else {
        // New-bin candidate: penalize, more so late in the stream.
        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if n as f64 > cap * 0.6 {
            score -= 6.0;
        }
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if n > 0 && bin_capacity - item_size == n {
            score -= 12.0;
        }
        if fragmentation < 0.12 && progress > 0.1 {
            score += 4.0;
        }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if n > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= n {
                let after = fresh_post - n;
                if after == 0 {
                    score -= 18.0;
                } else if after <= n / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
                if after >= n && after - n < 8 {
                    score -= 5.0;
                }
                if item_size > 0 && bin_capacity % item_size == 0 {
                    score -= 6.0;
                }
                // NEW: fresh-bin divisibility by the pair sum — a capacity that
                // exactly partitions into (item + next) repeats is a perfect bin.
                let pair = item_size + n;
                if pair > 0 && bin_capacity % pair == 0 {
                    score -= 7.0;
                }
            } else if n <= bin_capacity {
                score += 4.0;
            }
        }
        if pr > 0 && pr <= 8 {
            score -= 5.0;
        }
        // NEW: when open bins are heavily fragmented, opening fresh is cheap.
        if fragmentation > 0.45 && open_bins_count > 5 {
            score -= (fragmentation - 0.45) * 20.0;
        }
    }

    // NEW: global dead-space tilt — favor whichever placement leaves the
    // post-residual closest to a multiple of the next item (future-proofing).
    if n > 0 && pr >= n {
        let slack = pr - n;
        if slack > 0 && slack < 6 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero gets strongly favored.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 45.0 * tightness * tightness;

    // Lookahead: if the next item can exactly consume the post residual,
    // this placement is perfect; reward it heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item still fits here: mild reward proportional to fill
            let nxt_fill = next_item_size as f64 / (post_residual as f64 + 0.5);
            score -= 25.0 * nxt_fill;
        } else {
            // next item cannot use leftover: penalize large dead space
            let dead = post_residual as f64;
            score += 0.15 * dead * (dead / cap);
        }
    } else {
        // last item: just minimize residual
        score -= 10.0 * tightness;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let pressure = (open_bins_count as f64) / (1.0 + (total_items as f64).sqrt());
    score += 2.0 * pressure * (post_residual as f64 / cap);

    // Time horizon: late in the stream, be greedy about residual;
    // early, allow more exploration (weaken tight-fit bias slightly).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * tightness;

    // Compare against the mean residual of open bins: bins with residual
    // far below mean are scarce-space bins; filling them is valuable.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let scarcity = (mean_residual - res_f) / cap;
        if scarcity > 0.0 {
            score -= 12.0 * scarcity;
        } else {
            score += 4.0 * (-scarcity);
        }
    }

    // New-bin candidate handling: an empty bin has maximal residual.
    // Make it attractive only when the item is large or no good fit exists.
    if bin_residual == bin_capacity {
