        if next_item_size > 4 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 10.0 {
                score += (10.0 - miss) * (10.0 - miss) * 0.35;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: prefer small post-residual (tight fit)
    let mut score = pr;

    // Normalized residual ratio, smooth polynomial coupling with stream progress
    let r = pr / cap; // in [0,1]
    let p = progress.clamp(0.0, 1.0);

    // Early in the stream: keep residuals flexible (penalize very small residuals less,
    // penalize mid-range residuals more). Late: chase tight fits aggressively.
    let flexibility = (1.0 - p) * (r * (1.0 - r)) * 8.0; // smooth hump favoring mid residuals early
    score += flexibility;

    // Tight-fit reward: smooth cubic decay of reward as residual grows
    let tightness = (1.0 - r).powi(3) * (6.0 + 14.0 * p);
    score -= tightness;

    // Dead-space penalty: residual too small for lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let waste = (nxt - pr) / nxt;
            score += waste * (8.0 + 12.0 * p);
        } else {
            // Reward bins that can also host the next item (chain fit), smoothly
            let chain = 1.0 - (pr - nxt) / cap;
            score -= chain * (2.0 + 4.0 * p);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 5.0 + 10.0 * p;
    }

    // New-bin candidate handling: mildly attractive when many bins are open and residuals
    // are low / stream is early; penalized otherwise so tight fits win.
    if is_new_bin {
        let mean_r_norm = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score = score * 0.0 + 30.0
            - (1.0 - mean_r_norm) * 10.0
            - pressure * 12.0
            - (1.0 - p) * 6.0
            + mean_r_norm * 14.0;
    }

    // Mild global regularization toward low-mean-residual states
    score += (mean_residual / cap).clamp(0.0, 1.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;

    // Dead-space avoidance scaled to what's actually usable next.
    let min_useful = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        score += (min_useful - post_residual) as f64 * 6.0;
        if post_residual <= 5 {
            score += 25.0;
        }
        if post_residual < min_useful / 2 {
            score += (min_useful / 2 - post_residual) as f64 * 4.0;
        }
    }

    // Tight fit reward: quadratic near-full bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.80 {
        score -= (fit_ratio - 0.80) * (fit_ratio - 0.80) * 90.0;
    }
    if fit_ratio > 0.97 {
        score -= 14.0;
        if post_residual == 0 {
            score -= 6.0;
        }
    }
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: prefer using the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
        let leftover = bin_residual - item_size;
        if leftover <= 5 { score -= 8.0; }
        if next_item_size > 0 && leftover > next_item_size && leftover - next_item_size < 8 {
            score += 7.0;
        }
    }
    if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fragmentation = mean_residual / cap;

    // Residual "primed" relative to next item.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let gap = bin_residual as i64 - next_item_size as i64;
        if gap >= 0 && gap < 12 {
            score -= 8.0 - gap as f64 * 0.5;
        } else if gap < 0 && (-gap) < next_item_size as i64 {
            score += (-gap) as f64 * 0.30;
        }
    }

    if bin_residual != bin_capacity {
        score -= pressure;
        if progress < 0.3 && fragmentation < 0.15 {
            score -= (bin_residual as f64 / cap) * 3.0;
        }
        // Deep-fill bias — bins closest to closure get tilted harder as
        // the stream advances, so we consolidate rather than sprawl.
        let res_ratio = bin_residual as f64 / cap;
        if res_ratio < 0.25 {
            score -= (0.25 - res_ratio) * 14.0 * (1.0 + progress);
        }
        // NEW: exact-closure chase — if this placement empties the bin
        // outright, reward proportionally to how full the bin already was.
        if post_residual == 0 {
            score -= (1.0 - res_ratio) * 10.0;
        }
    } else {
        // New-bin candidate: penalize, more so late in the stream.
        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if next_item_size as f64 > cap * 0.6 {
            score -= 6.0;
        }
        if mean_residual > cap * 0.35 {
            score -= 4.0;
        }
        if post_residual > 0 && post_residual <= 8 {
            score -= 5.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 12.0;
        }
        if fragmentation < 0.12 && progress > 0.1 {
            score += 4.0;
        }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if next_item_size > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= next_item_size {
                let after = fresh_post - next_item_size;
                if after == 0 {
                    score -= 18.0;
                } else if after <= next_item_size / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
            }
        }
        // Fragmented open bins make a fresh bin attractive.
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
        // NEW: opening a fresh bin is best when it promises a near-perfect
        // multi-item tiling; reward when the fresh residual is a close
        // multiple of the next item, penalize awkward fresh leftovers.
        if next_item_size > 0 {
            let fresh_post = bin_capacity - item_size;
            let m = fresh_post / next_item_size.max(1);
            let rem = fresh_post % next_item_size.max(1);
            if m >= 2 && rem <= 3 {
                score -= (m as f64) * 3.0;
            } else if rem > 3 && rem < next_item_size {
                score += rem as f64 * 0.40;
            }
        }
    }

    // Prefer bins whose residual is below average, with convex tilt.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= dev * 0.20;
        if dev > 0.0 {
            score -= dev * 0.05;
        }
    }

    // Lookahead: reward when next item fits snugly in post residual.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 10.0;
    }
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 14.0 + (item_size as f64 / cap) * 4.0;
    }

    // Three-item chain potential.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next > 0 && after_next <= 12 {
            score -= 5.0;
        }
        if after_next >= next_item_size + next_item_size / 2 && after_next <= 2 * next_item_size {
            score -= 3.0;
        }
        if next_item_size >= 3 && next_item_size <= 12 && after_next % next_item_size == 0 {
            score -= 3.5;
        }
    }

    // Quadratic waste penalty for large leftovers.
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / cap;
        if waste_ratio > 0.5 {
            score += (waste_ratio - 0.5) * (waste_ratio - 0.5) * 40.0 + (waste_ratio - 0.5) * 10.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
        // Escalating terminal-waste penalty — dead space below smallest items.
        if post_residual <= 3 && next_item_size > post_residual {
            score += 12.0;
        }
        // Mid-band dead zone — residuals just below next_item_size waste space;
        // scale the penalty with stream progress since late waste is costlier.
        if next_item_size > 4 && post_residual < next_item_size && post_residual > 3 {
            score += (next_item_size - post_residual) as f64 * (0.55 + 0.30 * progress);
        }
        // NEW: stranded-fragment guard — leftover that can't hold even the
        // smallest plausible future item (<= 4) is permanent waste.
        if post_residual <= 4 {
            score += (4 - post_residual) as f64 * 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly (harmonic depth of fit).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic-class penalty: residuals divisible into small classes are more reusable.
        let pr = post_residual;
        let class_penalty: f64 = if pr <= 10 {
            -60.0 // tiny dead space, still very usable
        } else if pr <= 20 {
            -25.0
        } else if pr % 10 == 0 {
            -15.0 // decade-aligned residuals pair well with common sizes
        } else if pr <= 40 {
            0.0
        } else if pr <= 60 {
            15.0
        } else {
            35.0 // large residuals: prefer spreading load elsewhere
        };
        score += class_penalty;

        // Fractional capacity coupling: tightness ratio bonus.
        let tight = item_size as f64 / cap;
        score -= 40.0 * tight * tight; // favor bins that the item fills deeply
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 10.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only open a new bin when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and scarcity.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 120.0 - 40.0 * progress + 5.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a bin
        }
        // Avoid opening new bins when mean residual across open bins is large.
        score += 0.8 * mean_residual;
    } else {
        // Slight global pressure: prefer filling existing bins when many are open.
        score -= 2.0 * open_bins_count as f64;
        // Deviation from mean residual: prefer bins below mean (differentially filling).
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity.max(1) as f64;
    let n = next_item_size;

    // Harmonic residue classes: reward reusable remainders, punish awkward gaps.
    if pr < 12 {
        score -= 28.0 + (12 - pr) as f64 * 3.0;
        if pr == 0 {
            score -= 14.0;
        }
        if n > 0 && pr >= 1 && pr <= 3 && n > pr {
            score += 5.0;
        }
        if n > 0 && pr >= 1 && pr <= 3 && n == pr {
            score -= 10.0;
        }
        if n > 0 && pr >= n && pr - n <= 1 {
            score -= 9.0;
        }
    } else if pr < 28 {
        let d = (28 - pr) as f64;
        score += 11.0 + d * (1.0 + 0.03 * d);
        if n >= 12 && n <= pr {
            score -= 18.0;
        }
        if n >= 8 && pr >= 2 * n {
            score -= 9.0;
        }
        if n > 0 && pr >= n && (pr - n) < 4 {
            score -= 4.0;
        }
    } else {
        if pr % 5 == 0 { score -= 5.5; }
        if pr % 10 == 0 { score -= 4.5; }
        if pr % 25 == 0 { score -= 3.5; }
        if n > 0 && pr > n && pr - n <= 10 {
            score -= 4.5;
        }
        if n >= 10 {
            let r = pr % n;
            if r > 0 && n - r <= 4 {
                score -= 3.0;
            }
        }
        if n >= 15 && pr >= n + n / 2 {
            score -= 2.5;
        }
        if n > pr && pr > 28 && pr < 45 {
            score += 3.5;
        }
        if n >= 3 && n <= 12 && pr % n == 0 && pr > 0 {
            score -= 4.0;
        }
    }

    // Dead-space avoidance: residuals too small for the next item are waste.
    let min_useful = if n > 0 { n.min(80) } else { 10 };
    if pr > 0 && pr < min_useful {
        score += (min_useful - pr) as f64 * 6.0;
        if pr <= 5 {
            score += 25.0;
        }
        if pr < min_useful / 2 {
            score += (min_useful / 2 - pr) as f64 * 4.0;
        }
        if n > 4 && pr > 3 {
            score += (n - pr) as f64 * 0.55;
        }
        if pr <= 3 && n > pr {
            score += 12.0;
        }
    }

    // Perfect closure is the strongest compaction signal.
    if pr == 0 {
        score -= 30.0;
    }

    // Quadratic waste penalty for large leftovers.
    if pr > 0 {
        let waste_ratio = pr as f64 / cap;
        if waste_ratio > 0.5 {
            score += (waste_ratio - 0.5) * (waste_ratio - 0.5) * 40.0 + (waste_ratio - 0.5) * 10.0;
        }
        if n > 0 && pr < n {
            score += (n - pr) as f64 * 0.35;
        }
    }

    // Tight fit reward: quadratic near-full bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.80 {
        score -= (fit_ratio - 0.80) * (fit_ratio - 0.80) * 90.0;
    }
    if fit_ratio > 0.97 {
        score -= 14.0;
        if pr == 0 {
            score -= 6.0;
        }
    }

    // Two-step lookahead: chain fits strongly rewarded.
    if n > 0 {
        if n == pr {
            score -= 52.0 + (item_size as f64 / cap) * 4.0;
        } else if n < pr {
            let npr = pr - n;
            if npr < 12 { score -= 15.0; }
            if npr % 10 == 0 { score -= 5.0; }
            if npr % 25 == 0 { score -= 3.5; }
            if npr >= n && npr < 40 { score -= 2.5; }
            if npr >= 20 { score -= 4.0; }
            if n >= 6 && npr >= 2 * n {
                score -= 3.5 + (npr / n.max(1)) as f64;
            }
            if npr > 15 && npr < 25 && npr % 5 != 0 {
                score += 2.5;
            }
            if npr > 0 && npr <= 12 {
                score -= 5.0;
            }
            if npr >= n + n / 2 && npr <= 2 * n {
                score -= 3.0;
            }
            if n >= 3 && n <= 12 && npr % n == 0 {
                score -= 3.5;
            }
            // Double-chain lookahead: bin can absorb two more items.
            if npr >= n {
                let npr2 = npr - n;
                if npr2 == 0 {
                    score -= 7.0;
                } else if npr2 < 6 {
                    score -= 4.0;
                } else if npr2 >= n && npr2 < 25 {
                    score -= 2.0;
                }
            }
        } else {
            let shortfall = n - pr;
            score += 12.0 + shortfall as f64 * 0.06;
            if shortfall <= 4 { score -= 6.0; }
        }
        // Residual "primed" relative to next item.
        let gap = bin_residual as i64 - n as i64;
        if gap >= 0 && gap < 12 && bin_residual != bin_capacity {
            score -= 8.0 - gap as f64 * 0.5;
        } else if gap < 0 && (-gap) < n as i64 && bin_residual != bin_capacity {
            score += (-gap) as f64 * 0.30;
        }
    } else {
        score -= 8.0;
    }

    // Tightness scaled by fill ratio.
    let fill_ratio = 1.0 - bin_residual as f64 / cap;
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += tightness * (7.0 + 7.0 * fill_ratio);

    // Deviation from mean residual: nearly-full bins preferred (convex tilt).
    let dev = pr as f64 - mean_residual;
    score += dev * 0.40;
    if bin_residual != bin_capacity && dev < 0.0 {
        score += dev * 0.05;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity && bin_residual >= item_size {
        score -= 34.0;
        if bin_residual - item_size <= 5 { score -= 10.0; }
        if n > 0 && bin_residual - item_size >= n {
            score -= 6.0;
        }
        let leftover = bin_residual - item_size;
        if n > 0 && leftover > n && leftover - n < 8 && leftover > 30 {
            score += 9.0;
        }
        if leftover == 0 { score -= 6.0; }
    }
    if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 7.5;
    }

    // Open-bin pressure (logarithmic to tolerate many open bins).
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fragmentation = mean_residual / cap;

    if bin_residual != bin_capacity {
        score -= pressure;
        let res_ratio = bin_residual as f64 / cap;
        if res_ratio < 0.25 {
            score -= (0.25 - res_ratio) * 14.0;
        }
        if progress < 0.3 && fragmentation < 0.15 {
            score -= res_ratio * 3.0;
        }
        // Escalate deep-fill bias as stream progresses.
        if progress > 0.5 && res_ratio < 0.5 {
            score -= (0.5 - res_ratio) * (progress - 0.5) * 20.0;
        }
        // NEW: mid-band dead-zone tilt — residuals just below the next item
        // size can never be reclaimed; penalize harder late in the stream.
        if n > 4 && pr < n && pr > 3 {
            score += (n - pr) as f64 * (0.30 + 0.60 * progress);
        }
    } else {
        // New-bin candidate: penalize, more so late in the stream.
        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if n as f64 > cap * 0.6 {
            score -= 6.0;
        }
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if n > 0 && bin_capacity - item_size == n {
            score -= 12.0;
        }
        if fragmentation < 0.12 && progress > 0.1 {
            score += 4.0;
        }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if n > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= n {
                let after = fresh_post - n;
                if after == 0 {
                    score -= 18.0;
                } else if after <= n / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
                // Triple-completion potential in a fresh bin.
                if after >= n && after - n < 8 {
                    score -= 5.0;
                }
                // Fresh-bin divisibility — exact partition is a perfect bin.
                if item_size > 0 && bin_capacity % item_size == 0 {
                    score -= 6.0;
                }
            } else if n <= bin_capacity {
                score += 4.0;
            }
        }
        if pr > 0 && pr <= 8 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    // Assume minimum item size 1, but treat tiny gaps (< 10) as near-unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Gaps in 10..=20 are only usable by small items; moderate penalty scaled by gap smallness.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward near-perfect fits strongly (waste-minimization).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward bins whose residual closely matches the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.35;

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins
    // rather than spreading; makes new-bin candidate less attractive as open_bins_count grows.
    score += 0.9 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it attractive only when the item would leave a large,
    // reusable residual and existing fits are poor; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: grows with stream progress (late bins cost more
        // since fewer items remain to fill them) and with number of open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 + 70.0 * progress;

        // If the item nearly fills a fresh bin, opening a new one is fine.
        if item_size >= bin_capacity - 5 {
            score -= 120.0;
        }
        // If lookahead item can pair with the leftover of this item in a fresh bin,
        // opening a new bin is more attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
        // If only one existing bin fits, discourage the fresh bin (use the last chance).
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    } else {
        // Existing-bin placement: slight bonus when the leftover aligns with the
        // lookahead item, enabling chained fills.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
