pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but penalize dead space that nothing can use later.
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: this bin will be closed perfectly
        } else if next_item_size <= post_residual {
            // partial lookahead fit: reward proportionally to how well next item uses leftover
            let usage = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * usage;
        } else {
            // next item cannot fit here: penalize small unusable leftovers
            if post_residual < 10 {
                score += 25.0; // dead space too small for anything (min item 1..100 range guard)
            }
            // penalize if leftover is below typical small-item sizes
            if post_residual < 20 && post_residual < next_item_size {
                score += 15.0;
            }
        }
    }

    // Relative-to-mean-residual coupling: prefer bins that are more filled than average.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.5;
    } else {
        score += (resid_f - mean_residual) * 0.25;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Slight penalty so we only open new bins when open bins are genuinely bad fits.
        score += 12.0;
        // Early in the stream, opening bins is cheap-ish; later, avoid proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If many bins already open, discourage another one.
        score += open_bins_count as f64 * 1.5;
        // If lookahead item is huge relative to capacity, a fresh bin is attractive.
        if next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild waste penalty scaled by fill ratio (tight packing pressure).
    let fill = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 8.0 * fill;

    score
}

