    if bin_residual != bin_capacity {
        score -= pressure;
        let res_ratio = bin_residual as f64 / cap;
        if res_ratio < 0.25 {
            score -= (0.25 - res_ratio) * 14.0;
        }
        if progress < 0.3 && fragmentation < 0.15 {
            score -= res_ratio * 3.0;
        }
        if progress > 0.5 && res_ratio < 0.5 {
            score -= (0.5 - res_ratio) * (progress - 0.5) * 20.0;
        }
        // NEW: closure-urgency — a bin that fits the item almost exactly and
        // is already deep should dominate everything; combine tight fit with
        // small post-residual into a compounding closure bonus.
        let leftover = bin_residual - item_size;
        if leftover <= 3 {
            score -= 16.0 - leftover as f64 * 3.0;
        } else if leftover <= 8 && n > 0 && leftover < n {
            score -= 4.0;
        }
        // NEW: residual-band alignment — reward bins whose post-residual
        // matches common small-item sizes (1..=12) exactly.
        if n > 0 && n <= 12 && pr == n {
            score -= 6.0;
        }
    } else {
        // New-bin candidate: penalize, more so late in the stream.
        score += 9.0 + pressure + progress * 3.0 + fragmentation * 10.0;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if n as f64 > cap * 0.6 {
            score -= 6.0;
        }
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
        if item_size > 55 && fragmentation < 0.30 {
            score -= 8.0 + (item_size - 55) as f64 * 0.20;
        }
        if n > 0 && bin_capacity - item_size == n {
            score -= 12.0;
        }
        if fragmentation < 0.12 && progress > 0.1 {
            score += 4.0;
        }
        if progress > 0.65 {
            score += 6.0 + (progress - 0.65) * 30.0;
        }
        // Pair-completion lookahead in a fresh bin.
        if n > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= n {
                let after = fresh_post - n;
                if after == 0 {
                    score -= 18.0;
                } else if after <= n / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
                if after >= n && after - n < 8 {
                    score -= 5.0;
                }
                if item_size > 0 && bin_capacity % item_size == 0 {
                    score -= 6.0;
                }
            } else if n <= bin_capacity {
                score += 4.0;
            }
        }
        if pr > 0 && pr <= 8 {
            score -= 5.0;
        }
        // NEW: resist opening a fresh bin when any open bin can still close
        // perfectly on this item (post_residual == 0 elsewhere).
        if fitting_bins_count > 0 && n > 0 && n == pr {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward dead space (small but nonzero residuals).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: bonus if the post residual can host the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty if it's close in size.
        score += 2.0 * (1.0 - (next_item_size as f64 / bin_capacity as f64));
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: usually worse than reusing an open bin, unless
    // no open bin fits well (high fill ratio means poor fit elsewhere).
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * fill_ratio;
        // Late in the stream, opening fresh bins is more acceptable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * progress;
        // If many bins are open with large mean residual, prefer reuse.
        score += 0.15 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Prefer bins below the mean residual (consolidate emptier bins? no —
    // prefer filling bins below mean to keep large residuals available).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
