pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate leftover space; late, squeeze residuals hard.
    let squeeze = 1.0 + 2.0 * progress * progress + 1.5 * progress * (1.0 - progress);
    score += (pr * pr) / cap * squeeze * 0.05;

    // Reward tight fits (post_residual near zero) with a smooth bowl.
    let tight = 1.0 - (pr / cap);
    score -= tight * tight * 3.0;

    // Penalize opening a brand-new bin when it is not necessary.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 8.0 + 6.0 * progress + 4.0 * scarcity;
        // Opening is more attractive only if the next item likely fits the new bin well.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            let fit_quality = 1.0 - ((cap - nxt) / cap);
            score -= 5.0 * fit_quality * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead: if next item exactly fills this bin's post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 12.0;
    } else if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += (gap / cap) * 4.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates below the mean (more committed bins).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * 2.0;

    // Mild penalty proportional to number of open bins to discourage bin sprawl.
    score += (open_bins_count as f64).ln() * 0.5 * (1.0 - progress);

    score
}

