pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size of 1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 + (10.0 - post_residual as f64) / 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    } else if post_residual <= 20 {
        // Marginal gap: moderate penalty scaled by proximity to uselessness.
        score += 15.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward filling the bin deeply (low post_residual relative to capacity).
    let fill_ratio = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // existing bins; penalize opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()) * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure.
        score += 30.0 + 20.0 * pressure;
    } else {
        score -= 8.0 * pressure.min(3.0);
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement strongly; if next item cannot fit here anyway,
    // slight neutralization of the dead-space penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual && next_item_size >= post_residual.saturating_sub(10) {
            score -= 15.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here; a tiny dead gap is less harmful.
            if post_residual <= 10 {
                score -= 20.0;
            }
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (tighter bins) when the item fits well.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.3 * dev; // bins tighter than mean get lower score
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity.max(1) as f64;
    let n = next_item_size;

    // Harmonic residue classes: reward reusable remainders, punish awkward gaps.
    if pr < 12 {
        score -= 28.0 + (12 - pr) as f64 * 3.0;
        if pr == 0 {
            score -= 14.0;
        }
        if n > 0 && pr >= 1 && pr <= 3 && n > pr {
            score += 5.0;
        }
        if n > 0 && pr >= 1 && pr <= 3 && n == pr {
            score -= 10.0;
        }
        if n > 0 && pr >= n && pr - n <= 1 {
            score -= 9.0;
        }
    } else if pr < 28 {
        let d = (28 - pr) as f64;
        score += 11.0 + d * (1.0 + 0.03 * d);
        if n >= 12 && n <= pr {
            score -= 18.0;
        }
        if n >= 8 && pr >= 2 * n {
            score -= 9.0;
        }
        if n > 0 && pr >= n && (pr - n) < 4 {
            score -= 4.0;
        }
    } else {
        if pr % 5 == 0 { score -= 5.5; }
        if pr % 10 == 0 { score -= 4.5; }
        if pr % 25 == 0 { score -= 3.5; }
        if n > 0 && pr > n && pr - n <= 10 {
            score -= 4.5;
        }
        if n >= 10 {
            let r = pr % n;
            if r > 0 && n - r <= 4 {
                score -= 3.0;
            }
        }
        if n >= 15 && pr >= n + n / 2 {
            score -= 2.5;
        }
        if n > pr && pr > 28 && pr < 45 {
            score += 3.5;
        }
        if n >= 3 && n <= 12 && pr % n == 0 && pr > 0 {
            score -= 4.0;
        }
    }

    // Dead-space avoidance: residuals too small for the next item are waste.
    let min_useful = if n > 0 { n.min(80) } else { 10 };
    if pr > 0 && pr < min_useful {
        score += (min_useful - pr) as f64 * 6.0;
        if pr <= 5 {
            score += 25.0;
        }
        if pr < min_useful / 2 {
            score += (min_useful / 2 - pr) as f64 * 4.0;
        }
        if n > 4 && pr > 3 {
            score += (n - pr) as f64 * 0.55;
        }
        if pr <= 3 && n > pr {
            score += 12.0;
        }
