pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Reward near-exact fits (post_residual close to zero).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize leaving small unusable gaps (<10) unless it's an exact fit.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.05 * (post_residual as f64);
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    }
    // Penalize if next item would not fit here anyway and we waste space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 0.05 * post_residual as f64;
    }

    // Time horizon: early in the stream, be conservative with open bins;
    // late in the stream, prefer packing tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - fill_ratio);

    // Many open bins: discourage opening new ones, encourage consolidation.
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / bin_capacity as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: open only if current bins are very full or item huge.
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        score += 15.0 + 40.0 * mean_fill - 0.1 * open_bins_count as f64
                 - 0.2 * item_size as f64 * progress;
        if item_size > 60 && mean_fill > 0.6 {
            score -= 10.0;
        }
    }

    // Mild penalty relative to mean residual: prefer bins tighter than average.
    score += 0.03 * (bin_residual as f64 - mean_residual);

    score
}

