    let norm_pr = pr / cap;

    // Base: post-residual with polynomial shaping (dead space penalized super-linearly)
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Smooth interaction: post-residual value depends on stream progress
    // Early on, larger residuals are fine; late, we want tight packs.
    let progress_coupling = 2.0 * progress * (norm_pr - 0.5) * (norm_pr - 0.5) * cap;
    score += progress_coupling;

    // Lookahead: reward if next item fits in post_residual (smooth via ratio)
    if next_item_size > 0 {
        let fit_ratio = (next_item_size as f64 / (pr + 1.0)).min(1.0);
        let lookahead_reward = 12.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio) * (1.0 + progress);
        score -= lookahead_reward;
    }

    // Last-chance bin: strongly favor using it (avoid opening a bin)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 4.0 * progress;
