    // "usable" vs "dead" space classes. Residues 0 (perfect fit) are ideal;
    // tiny residues 1..=3 create near-unusable slivers -> penalize hard.
    let r = post_residual % 10;
    score -= if post_residual == 0 {
        60.0 // perfect fit: huge reward
    } else if r == 0 {
        25.0 // multiple of 10: harmonically compatible with typical items
    } else if r <= 3 {
        -18.0 // dead sliver: penalize
    } else if r <= 6 {
        -4.0
    } else {
        6.0
    };

    // Integer-division thresholds on post_residual: classify leftover into
    // quartile bands of capacity.
    let q = (post_residual * 4) / bin_capacity;
    score -= match q {
        0 => 30.0, // nearly full bin, good packing
        1 => 10.0,
        2 => 0.0,
        _ => -8.0, // leaving a half-empty bin is wasteful
    };

    // Coupling with lookahead: if next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
