        if post_residual <= 3 && next_item_size > post_residual {
            score += 12.0;
        }
        // Mid-band dead zone — residuals just below next_item_size waste space.
        if next_item_size > 4 && post_residual < next_item_size && post_residual > 3 {
            score += (next_item_size - post_residual) as f64 * 0.55;
        }
        // Residual-band coupling — few fitting bins make mid-band waste costlier.
        if fitting_bins_count <= 2 && next_item_size > 4 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.40;
        }
    }

    // NEW: exact residual matching — prefer bins whose current residual
    // equals the next item size, guaranteeing a perfect follow-up closure.
    if next_item_size > 0 && bin_residual != bin_capacity && bin_residual == next_item_size {
        score -= 16.0;
    }

    // NEW: two-step lookahead — reward when post residual can hold the next
    // item AND the remainder can hold a third item of similar size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= next_item_size && r2 < 2 * next_item_size {
            score -= 4.0 + (2 * next_item_size - r2) as f64 * 0.30;
        }
        // Bonus when the leftover after next is small enough to close the bin.
        if r2 > 0 && r2 <= 4 {
            score -= 6.0;
        }
    }

    // NEW: early-stream consolidation — with few open bins and low mean
    // residual, push harder toward filling existing bins rather than opening.
    if progress < 0.25 && open_bins_count < 6 {
        if bin_residual != bin_capacity {
            score -= 3.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity.max(1) as f64;
    let n = next_item_size;

    // Dead-space guard: residuals too small to hold the next item are costly.
    let min_useful = if n > 0 { n.min(80) } else { 10 };
    if pr > 0 && pr < min_useful {
        score += (min_useful - pr) as f64 * 5.0;
        if pr <= 4 {
            score += 22.0;
        }
        if pr < min_useful / 2 {
            score += (min_useful / 2 - pr) as f64 * 4.0;
        }
    }

    // Harmonic residue classes: reward reusable remainders.
    if pr < 12 {
        score -= 28.0 + (12 - pr) as f64 * 3.0;
        if pr == 0 {
            score -= 14.0;
        }
        if n > 0 && pr >= 1 && pr <= 3 && n > pr {
            score += 5.0;
        }
        if n > 0 && pr >= 1 && pr <= 3 && n == pr {
            score -= 10.0;
        }
        if n > 0 && pr >= n && pr - n <= 1 {
            score -= 9.0;
        }
    } else if pr < 28 {
        let d = (28 - pr) as f64;
        score += 11.0 + d * (1.0 + 0.03 * d);
        if n >= 12 && n <= pr {
            score -= 18.0;
        }
        if n >= 8 && pr >= 2 * n {
            score -= 9.0;
        }
        if n > 0 && pr >= n && (pr - n) < 4 {
            score -= 4.0;
        }
    } else {
        if pr % 5 == 0 { score -= 5.5; }
        if pr % 10 == 0 { score -= 4.5; }
        if pr % 25 == 0 { score -= 3.5; }
        if n > 0 && pr > n && pr - n <= 10 {
            score -= 4.5;
        }
        if n >= 10 {
            let r = pr % n;
            if r > 0 && n - r <= 4 {
                score -= 3.0;
            }
        }
        if n >= 15 && pr >= n + n / 2 {
            score -= 2.5;
        }
        if n > pr && pr > 28 && pr < 45 {
            score += 3.5;
        }
    }

    // Two-step lookahead: chain fits strongly rewarded.
    if n > 0 {
        if n == pr {
            score -= 52.0;
        } else if n < pr {
            let npr = pr - n;
            if npr < 12 { score -= 15.0; }
            if npr % 10 == 0 { score -= 5.0; }
            if npr % 25 == 0 { score -= 3.5; }
            if npr >= n && npr < 40 { score -= 2.5; }
            if npr >= 20 { score -= 4.0; }
            if n >= 6 && npr >= 2 * n {
                score -= 3.5 + (npr / n.max(1)) as f64;
            }
            if npr > 15 && npr < 25 && npr % 5 != 0 {
                score += 2.5;
            }
            // NEW: three-item chain potential.
            if npr > n {
                let after = npr - n;
                if after <= 12 {
                    score -= 5.0;
                }
                if n >= 3 && n <= 12 && after % n == 0 {
                    score -= 3.5;
                }
            }
        } else {
            let shortfall = n - pr;
            score += 12.0 + shortfall as f64 * 0.06;
            if shortfall <= 4 { score -= 6.0; }
            // NEW: mid-band dead zone penalty (just below next item size).
            if shortfall > 0 {
                score += shortfall as f64 * 0.35;
            }
        }
    } else {
        score -= 8.0;
    }

    // Tightness scaled by fill ratio, with extra reward for near-perfect fits.
    let fill_ratio = 1.0 - bin_residual as f64 / cap;
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += tightness * (7.0 + 7.0 * fill_ratio);
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.80 {
        // NEW: quadratic near-full bonus (borrowed strength).
        score -= (fit_ratio - 0.80) * (fit_ratio - 0.80) * 70.0;
    }
    if fit_ratio > 0.97 {
        score -= 12.0;
        if pr == 0 {
            score -= 6.0;
        }
    }
    if pr == 0 {
        score -= 30.0;
    }

    // Deviation from mean residual: nearly-full bins preferred.
    score += (pr as f64 - mean_residual) * 0.40;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity && bin_residual >= item_size {
        score -= 34.0;
        if bin_residual - item_size <= 5 { score -= 10.0; }
        if n > 0 && bin_residual - item_size >= n {
            score -= 6.0;
        }
        let leftover = bin_residual - item_size;
        if n > 0 && leftover > n && leftover - n < 8 && leftover > 30 {
            score += 9.0;
        }
        if leftover == 0 { score -= 6.0; }
    }
    if fitting_bins_count == 2 && bin_residual != bin_capacity {
        score -= 7.5;
    }

    // New-bin candidate: attractive only when open bins are fragmented or item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        score += 37.0 + fragmentation * 24.0 - progress * 7.0;
        if item_size > 55 {
            score -= 13.0 + (item_size - 55) as f64 * 0.30;
        }
        if n >= 55 {
            score += 16.0;
        }
        if open_bins_count < 3 {
            score -= 10.0;
        }
        if fragmentation > 0.45 && item_size < 40 {
            score += 7.0;
        }
        if n > 0 && item_size < bin_residual && bin_residual - item_size == n {
            score += 22.0;
        }
        if item_size < 25 && mean_residual > item_size as f64 * 2.0 {
            score += 6.0;
        }
        if progress > 0.65 {
            score += 8.0 + (progress - 0.65) * 34.0;
        }
        if progress >= 0.25 && progress <= 0.65 && item_size <= 45 {
            score += (45 - item_size) as f64 * 0.22 * (1.0 - fragmentation).max(0.0);
        }
        if fitting_bins_count >= 4 && item_size < 35 {
            score -= 5.0;
        }
        if n > 20 && mean_residual < n as f64 * 0.8 {
            score -= 6.0;
        }
        if n > 0 && item_size <= bin_capacity - n && bin_capacity - item_size == n {
            score -= 12.0;
        }
        if n > 0 && pr % 10 == 0 && pr <= n {
            score += 9.0;
        }
        if fitting_bins_count == 0 {
            score -= 14.0;
        }
        // NEW: pair-completion lookahead in a fresh bin.
        if n > 0 {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= n {
                let after = fresh_post - n;
                if after == 0 {
                    score -= 18.0;
                } else if after <= n / 2 {
                    score -= 8.0;
                } else if after <= 12 {
                    score -= 4.0;
                }
            }
        }
        // NEW: fragmented open bins make a fresh bin attractive.
        if fragmentation > 0.30 && open_bins_count > 3 {
            score -= (fragmentation - 0.30) * 25.0;
        }
    } else {
        // NEW: deep-fill bias — bins whose residual is already small are
        // closest to closure; tilt harder as residual shrinks.
        let res_ratio = bin_residual as f64 / cap;
        if res_ratio < 0.25 {
            score -= (0.25 - res_ratio) * 14.0;
        }
    }

    // Mild open-bin pressure to discourage needless spreading.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item
    // (items >= 1, but typical useful chunks are larger) are pure waste.
    // Penalize tiny unusable gaps super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Reward near-perfect fits aggressively.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement chains perfectly; reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // If the next item cannot fit the post residual but the gap is large
    // enough to be reusable, mild reward; if gap is mid-sized and useless, penalize.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins; opening new
    // bins is penalized via the empty-bin candidate getting a fixed surcharge.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Mean-residual alignment: bins with residual far below mean are more
    // "settled"; placing there consumes fragmented space efficiently.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Early in the stream, tolerate slightly looser fits to keep flexibility;
    // late in the stream, be strict about dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
