pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward post_residual matching next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits here afterward: mildly good, tighter the better.
            score -= 120.0 - (post_residual - next_item_size) as f64 * 0.8;
        } else {
            // Dead space relative to next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Compare against mean residual: bins below mean residual are tight; prefer filling them.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.6;

    // Last-chance bin bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: prefer it only when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 300.0;
        } else {
            // Penalize opening new bin when alternatives exist, scaled by best-fit quality.
            score += 150.0 + mean_residual * 0.3;
        }
    }

    // Late in stream, consolidate: discourage leaving many fragments.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;
    score += open_bins_count as f64 * 0.05;

    score
}

